 */
class AccountFigureTypeConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountFigureType {
            var item = AccountFigureType.DO_NOT_SHOW
            enumValues<AccountFigureType>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}