@kotlinx.serialization.Serializable
data class ChatDialog(

    //@ColumnInfo(name = "id")
    @SerialName("dialogId") var dialogId: String = "0",

    //@ColumnInfo(name = "chat_dialog_name")
    @SerialName("dialogName") private var dialogName: String = "0",

    //@ColumnInfo(name = "chat_dialog_photo")
    @SerialName("dialogPhoto") private var dialogPhoto: String = "",

    //@ColumnInfo(name = "chat_dialog_unread_count")
    @SerialName("unreadCount") private var unreadCount: Int = 0,

    //@ColumnInfo(name = "chat_dialog_mode")
    @SerialName("mode") var mode: Int = 0,

    //@ColumnInfo(name = "chat_dialog_pinned")
    @SerialName("is_pinned") var isPinned: Boolean = false,

    //@ColumnInfo(name = "chat_dialog_request")
    @SerialName("is_request") var isRequest: Boolean = false,

    //@ColumnInfo(name = "chat_dialog_users")
//    @TypeConverters(ChatUserListConverter::class)
    @SerialName("chatUsers") var chatUsers: MutableList<ChatUser> = mutableListOf(),


    //@Embedded
    @SerialName("lastMessageItem") var lastMessageItem: LastMessageItem? = null,

    //@ColumnInfo(name = "chat_messages")
//    @TypeConverters(ChatMessageConverter::class)
    @SerialName("messages") var messages: MutableList<ChatMessageItem>? = mutableListOf(),

    @SerialName("typingStatus") var typingStatus: String = "",

    var position: Int? = null

) {

    fun getId(): String = dialogId
    fun getDialogPhoto(): String = dialogPhoto
    fun getDialogName(): String = dialogName
    fun getUsers(): ArrayList<ChatUser> = ArrayList(chatUsers)
    fun getLastMessage(): ChatMessageItem? = lastMessageItem?.toChat()
    fun getUnreadCount(): Int = unreadCount
//    fun getLastMessageItem(): LastMessageItem? = lastMessageItem

    fun setDialogPhoto(dialogPhoto: String) {
        this.dialogPhoto = dialogPhoto
    }

    fun setDialogName(dialogName: String) {
        this.dialogName = dialogName
    }

    fun setUsers(users: ArrayList<ChatUser>) {
        this.chatUsers = users
    }

    fun setLastMessage(lastMessage: ChatMessageItem?) {
        this.lastMessageItem = lastMessage?.toLast()
    }

    /*fun setLastMessageItem(lastMessage: LastMessageItem?) {
        this.lastMessageItem = lastMessage
    }*/

   /* fun setLastMessage(lastMessage: LastMessageItem?) {
        this.lastMessageItem = lastMessage
    }*/

    fun setUnreadCount(unreadCount: Int) {
        this.unreadCount = unreadCount
    }
}