sealed class ProfileSelectPhotosEvent {
    //    data class SaveCropPhoto(val cropPath: String) : ProfileSelectPhotosEvent()
    data class UpdateVerificationProfile(val account: Account?) : ProfileSelectPhotosEvent()
    data object ShowOnBoardingNextPage : ProfileSelectPhotosEvent()
    data class PickPhotoManager(val fromGallery: Boolean, val callback: (String) -> Unit) : ProfileSelectPhotosEvent()
    data object ShowProfileVerification : ProfileSelectPhotosEvent()
    data class ShowCropPhotoPage(val photo: String?) : ProfileSelectPhotosEvent()
    data class ClearData(val data: String) : ProfileSelectPhotosEvent()
    data object OnBack : ProfileSelectPhotosEvent()
    data class ProfileFaceVerification(val credentials: AmplifyAuthorization) :
        ProfileSelectPhotosEvent()

    data object DeleteAvatarEvent : ProfileSelectPhotosEvent()
    data class UpdateAvatarEvent(val url: String) : ProfileSelectPhotosEvent()
}

class ProfileSelectPhotosVM(
    val fromPage: PhotosFromPage,
    private val viewModelCallback: (ProfileSelectPhotosEvent) -> Unit,
) : ViewModel() {

    private val fileRepository by di.instance<FileRepository>()
    private val accountRepository by di.instance<AccountRepository>()
    private val dialogManager by di.instance<IDialogManager>()
    private val amplitudeManager by di.instance<AmplitudeManager>()

    private val appKeys = accountRepository.getAppKeys()
    val userRegistered = appKeys.userRegistered

    //    private var adapter: ProfileSelectPhotosAdapter? = null
    private var isDestroy: Boolean = true
    private var recreatePage = false
    var isBtnShow = false

//    private var startPhotosList = mutableStateOf( mutableListOf<AccountPhoto>())

    var account: Account? = null

    val title = mutableStateOf("")
    val showBackBtn = mutableStateOf(true)
    val rightButtonTitle = mutableStateOf("")
    val shortOnboarding = mutableStateOf(false)
    val showProgress = mutableStateOf(false)

    private val startPhotosList = mutableListOf<AccountPhoto>()
    private val photos = mutableStateListOf<AccountPhoto>()
    private val _photosListFlow = MutableStateFlow(photos)
    val photosListFlow: StateFlow<List<AccountPhoto>> get() = _photosListFlow

    private var uploadPhoto = ""
    private val uploadPhotos: MutableList<String> = mutableListOf()
    private val lastAccountPhotos: MutableList<AccountPhoto> = mutableListOf()
    var firstPhoto: AccountPhoto? = null
    val selectedPhoto = mutableStateOf<Int?>(null)
    val showMenuPhotosBottomSheet = mutableStateOf(false)
    private var changeFirstPhoto = false
    var pickPhoto: String = ""
    val showCropPhotoScreen = mutableStateOf(false)

    init {
        if (!userRegistered && fromPage == PhotosFromPage.Onboarding) {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAddPhotoScreenShown)
        }

        if (!userRegistered) {
            showBackBtn.value = false
            shortOnboarding.value = accountRepository.isShortOnboardingFlow()
        }

        isBtnShow =
            fromPage == PhotosFromPage.Onboarding || fromPage == PhotosFromPage.VerificationDialog

        viewModelScope.launch(Dispatchers.Main) {
            account = accountRepository.getMyAccount()
            if (fromPage == PhotosFromPage.Onboarding) addPhotos(account?.photos)
            accountRepository.loadMyAccountPhotos(onSuccess = {
                addPhotos(it)
            }, onError = {
                accountRepository.loggedError(ScreenEnum.GetPhotosManager, error = it ?: "")
            })

            rightButtonTitle.value = getString(
                if (!isBtnShow) Res.string.nav_settings_done else Res.string.onboarding_start_btn_text_next
            )
            title.value = getString(
                if (userRegistered && fromPage != PhotosFromPage.VerificationDialog) Res.string.onboarding_select_photos_title else Res.string.onboarding_add_photo_title
            )
        }
    }


    fun addPhotoClick() {
        showMenuPhotosBottomSheet.value = true
    }

    fun rollbackPhoto(photoUrl: String) {
        if (photoUrl.isEmpty()) {
            selectedPhoto.value = null
            return
        }

        var rollbackPhotoIndex = 0
        photos.forEachIndexed { index, accountPhoto ->
            if (accountPhoto.url == photoUrl) rollbackPhotoIndex = index
        }
        selectedPhoto.value?.let { selectedPhotoIndex ->
            photos[selectedPhotoIndex] = photos[rollbackPhotoIndex].also {
                val photo = photos[selectedPhotoIndex]
                photos[rollbackPhotoIndex] = photo
                if (rollbackPhotoIndex == 0) {
                    lastAccountPhotos.clear()
                    lastAccountPhotos.addAll(photos)
                    changeFirstPhoto = true
                    CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                        if (accountRepository.getMyAccount()
                                ?.getVerificationStatus() == AccountVerificationStatus.VERIFIED
                        ) syncSortPositions()
                    }
                }
            }
        }

        selectedPhoto.value = null
    }

    fun longPhotoClick(photoUrl: String) {
        if (photoUrl.isEmpty()) return
        photos.forEachIndexed { index, accountPhoto ->
            if (accountPhoto.url == photoUrl) selectedPhoto.value = index
        }
    }

    fun deletePhotoClick(photoUrl: String) {
        if (photoUrl.isEmpty()) return
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            var position = -1
            photos.forEachIndexed { index, accountPhotos ->
                if (accountPhotos.url == photoUrl) position = index
            }
            if (position == 0 && accountRepository.getMyAccount()
                    ?.getVerificationStatus() == AccountVerificationStatus.VERIFIED && photos.size > 1
            ) {
                deleteFirstPhoto(photos[position])
            } else {
                deletePhoto(photos[position])
            }
        }
    }

    private fun deleteFirstPhoto(photo: AccountPhoto) {
        firstPhoto = photo
        lastAccountPhotos.clear()
        lastAccountPhotos.addAll(photos)
        photos.remove(photo)
        syncSortPositions()
    }

    fun addPhoto(cropPhoto: String) {
        if (cropPhoto.isEmpty()) return
        uploadPhotos.add(cropPhoto)
        photos.add(AccountPhoto(url = cropPhoto))
        if (photos.size == 1) changeFirstPhoto = true
        if (uploadPhoto.isEmpty()) uploadPhotos()
    }

    private fun uploadPhotos() {
        if (uploadPhotos.size == 0) {
            uploadPhoto = ""
            viewModelCallback.invoke(ProfileSelectPhotosEvent.UpdateAvatarEvent(uploadPhoto))
            return
        }
        uploadPhoto = uploadPhotos.first()

        fileRepository.uploadPhotoByPath(
            uploadPhoto,
            onSuccess = { update(it) }, onModerateError = {
                accountRepository.loggedError(ScreenEnum.ModeratePhotoManager, error = it)
                showMessage(Res.string.dialog_photo_moderation_error)
            }, onError = {
                when (it) {
                    "105101" -> showMessage(Res.string.dialog_verification_error_sort_photos)

                    "105102" -> showMessage(Res.string.dialog_photo_moderation_error)

                    else -> accountRepository.loggedError(
                        ScreenEnum.UploadPhotoManager,
                        error = it ?: ""
                    )
                }
//                onError()
            })
    }

    private fun update(photo: AccountPhoto?) {
        val position = photos.indexOf(AccountPhoto(url = uploadPhoto))
        if (photo != null && position >= 0) {
            photos[position] = photo
            uploadPhotos.remove(uploadPhoto)
        }
        if (position == 0 && changeFirstPhoto) {
            changeFirstPhoto = false
            viewModelCallback.invoke(ProfileSelectPhotosEvent.UpdateAvatarEvent(uploadPhoto))
        }
        uploadPhotos()
    }

    private fun showMessage(message: StringResource) {
        viewModelScope.launch(Dispatchers.Main) {
            dialogManager.showMessageDialog(getString(message))
        }
    }

    private fun addPhotos(accountPhotos: MutableList<AccountPhoto>?) {
        val sortedList = accountPhotos?.sortedBy { it.sortId } ?: mutableListOf()
        startPhotosList.addAll(sortedList)
        photos.addAll(sortedList)
        if (account?.avatar.isNullOrEmpty() && (account?.photos?.size ?: 0) > 0)
            changeFirstPhoto = true
    }

    fun onMenuPhotosClick() =
        viewModelCallback.invoke(ProfileSelectPhotosEvent.PickPhotoManager(true){
                pickPhoto = it
                showCropPhotoScreen.value = true
        })

    fun onMenuCameraClick() {
        val pickPhotoManager by di.instance<IPickPhotoManager>()
            pickPhotoManager.showPickFromCamera {
                val image = it as? String
                if (image != null) pickPhoto = image
                showCropPhotoScreen.value = true
            }
    }

    fun onMenuSelfDeleteClick() {} //= pickPhotoManager.onMenuSelfDeleteClick()
    fun onMenuCancelClick() {
        showMenuPhotosBottomSheet.value = false
    }

    private fun pickPhoto(result: Any?) {
        val image = result as String?
        image?.let {
            val cropType =
                if (fromPage != PhotosFromPage.Onboarding) CropPhotoType.CROP_PHOTO else CropPhotoType.CROP_PHOTO_ONBOARDING
//            router.route(Destination.ProfilePhotoCrop(it, cropType))
        }
    }

    fun clickedBtn(isDuplicate: Boolean = false) {
        isDestroy = false
        clickSystemBtn = false
        showProgress.value = true
        onButtonClick {
            if (photos.isEmpty()) {
                if (!userRegistered) {
                    AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationWithoutPhoto.name)
                    if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.photoNextTop.name)
                    else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.photoNextBottom.name)
                }
            } else {
                if (!userRegistered) {
                    if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.photoNextTop.name)
                    else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.photoNextBottom.name)

                    if (photos.size == 1)
                        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationWithOnePhoto.name)
                    else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationMoreThenOnePhoto.name)
                }
            }
            showNextPage()
        }
    }

    private fun onButtonClick(callback: () -> Unit = {}) {
        if (uploadPhotos.isNotEmpty()) {
            viewModelScope.launch(Dispatchers.Main) {
                val text = getString(Res.string.onboarding_upload_photos_not_all_upload)
                dialogManager.showMessageDialog(text)
            }
            showProgress.value = false
            return
        }

        if (photos.isEmpty() || startPhotosList == photos) callback()
        else syncSortPositions(callback)
    }


    private fun getItemPosition(photo: String): Int {
        var position = -1
        for (i in 0 until photos.size) {
            if (photos[i].url == photo) position = i
        }
        return position
    }

    private fun deletePhoto(photo: AccountPhoto) {
        val url = photo.url ?: ""
        fun removePhoto() {
            val index = getItemPosition(url)
            photos.remove(photo)
            if (photos.size == 0) viewModelCallback.invoke(ProfileSelectPhotosEvent.DeleteAvatarEvent)
            else if (index == 0) {
                val newAvatar = photos.first().url
                updateAvatar(newAvatar ?: "")
            }
            if (uploadPhotos.contains(url)) uploadPhotos.remove(url)
        }

        if (photo.id.isNotEmpty()) {
            fileRepository.deletePhoto(photo.id, onSuccess = { removePhoto() }, onError = {
                accountRepository.loggedError(ScreenEnum.DeletePhotoManager, error = it ?: "")
            })
        }/* else {
            if (uploadPhoto == url) {
                if (currentProgress >= 99) {
                    // onEvent(ErrorPhotoManager(R.string.dialog_photo_delete_error))
                } else {
                    fileRepository.stopUploadPhoto()
                    currentProgress = 0f
                    removePhoto()
                    uploadPhotos()
                }
            }*/ else {
            removePhoto()
        }
    }

    private fun syncSortPositions(callback: (() -> Unit)? = null) {
        if (callback != null) showProgress.value = true
        fileRepository.syncPhotos(photos, userRegistered, onSuccess = {
            firstPhoto?.let {
                returnLastPhotosList()
                deletePhoto(it)
                firstPhoto = null
            }
            if (changeFirstPhoto || (account?.avatar.isNullOrEmpty() && photos.size != 0)) {
                updateAvatar(photos[0].url ?: "")
            }
            callback?.invoke()
        }, onError = {
            if (it == "105007") {
                viewModelScope.launch {
                    showProgress.value = false
                    if (firstPhoto != null) {
                        val messageText =
                            getString(Res.string.dialog_verification_remove_photo_error)
                        dialogManager.showMessageDialog(messageText)
                        returnLastPhotosList()
                        firstPhoto = null
                        return@launch
                    }
                    val messageText = getString(Res.string.dialog_verification_error_sort_photos)
                    dialogManager.showMessageDialog(messageText)
                    returnLastPhotosList()
                }
            } else {
                accountRepository.loggedError(ScreenEnum.UpdateOrderPhotoManager, error = it ?: "")
                callback?.invoke()
            }
        })
    }

    private fun returnLastPhotosList() {
        photos.clear()
        photos.addAll(lastAccountPhotos)
    }

    fun syncPhotosIfNeed() {
        if (!isDestroy) return
        if (photos.size == 0) return
        fileRepository.syncPhotos(photos, userRegistered, onSuccess = {
            if (changeFirstPhoto || (account?.avatar.isNullOrEmpty() && photos.size != 0))
                updateAvatar(photos[0].url ?: "")
        }, onError = {
            accountRepository.loggedError(ScreenEnum.UpdateOrderPhotoManager, error = it ?: "")
        })
    }

    private fun updateAvatar(filePath: String, syncPhotos: Boolean = false) {
        changeFirstPhoto = false
        if (syncPhotos) syncPhotosIfNeed()
        viewModelCallback.invoke(ProfileSelectPhotosEvent.UpdateAvatarEvent(filePath))
    }

    fun updateVerificationProfile(myAccount: Account? = null) {
        viewModelScope.launch(Dispatchers.Main) {
            account = myAccount ?: accountRepository.getMyAccount()
        }
    }

    private fun showNextPage() {
        showProgress.value = false
        when (fromPage) {
            PhotosFromPage.Profile -> {
                EventBusManager.post(UploadCropPhoto())
                isDestroy = false
                viewModelCallback.invoke(ProfileSelectPhotosEvent.OnBack)
            }

            PhotosFromPage.Onboarding -> {
                amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAddPhotoScreenNextClicked)
                viewModelCallback.invoke(ProfileSelectPhotosEvent.ShowOnBoardingNextPage)
            }

            PhotosFromPage.VerificationDialog -> {
                if ((photos.size) <= 0) {
                    viewModelScope.launch(Dispatchers.Main) {
                        val title = getString(Res.string.verification_photos_empty_error_title)
                        val text = getString(Res.string.verification_photos_empty_error_text)
                        dialogManager.showMessageWithTitleDialog(title, text)
                    }
                } else {
                    showProgress.value = true
                    accountRepository.loadAmplifyCredentials(
                        onSuccess = {
                            viewModelCallback.invoke(
                                ProfileSelectPhotosEvent.ProfileFaceVerification(
                                    it
                                )
                            )
                            showProgress.value = false
                        },
                        onError = {
                            showProgress.value = false
                        }
                    )
                }
            }

            else -> {
                isDestroy = false
                if (!clickSystemBtn) viewModelCallback.invoke(ProfileSelectPhotosEvent.OnBack)
            }
        }
    }

    private fun clickedBtnAddMore() {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAddPhotoScreenPlusClicked)
//        supportFragmentManager?.let { pickPhotoManager.show(it) }
    }

    fun backButtonClick() {
        clickBackBtn = true
        isDestroy = false
        clickSystemBtn = false
        if (!isBtnShow) clickedBtn() else backPage()
    }

    private fun backPage() {
        onButtonClick {
            isDestroy = false
            viewModelCallback.invoke(ProfileSelectPhotosEvent.OnBack)
        }
    }

    private var clickSystemBtn = true
    private var clickBackBtn = false

    @UiThread
    fun backSystem(): Boolean {
        if (showMenuPhotosBottomSheet.value) {
            showMenuPhotosBottomSheet.value = false
            return false
        }
        isDestroy = false
        val result = clickSystemBtn
        return if (result) {
            if (userRegistered) {
                if (uploadPhotos.isEmpty()) onButtonClick()
                else {
                    clickSystemBtn = false
                    backPage()
                }
                true
            } else {
                val shortOnboarding = accountRepository.isShortOnboardingFlow()
                if (shortOnboarding) {
                    cancelRegistration()
                }
                //appKeys.onboardingCurrentPage = 0
                true
            }
        } else {
            appKeys.onboardingCurrentPage = 0
            false
        }
    }

    private fun cancelRegistration() {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCancelButtonClicked)
        dialogManager.showMessageDialog(
            EDialogType.DIALOG_DELETE_ACCOUNT_ONBOARDING,
            callback = {
                viewModelScope.launch(Dispatchers.Main) {
                    val errorTitle =
                        ResManager.getString(Res.string.nav_account_delete_error_title)
                    val errorText =
                        ResManager.getString(Res.string.nav_account_delete_error_text)
                    accountRepository.deleteAccount(onSuccess = {
                        accountRepository.getAppKeys().userBirthday = 0L
                        viewModelCallback.invoke(ProfileSelectPhotosEvent.ClearData("delete_acc_from_profile_photos"))
                    }, onError = {
                        dialogManager.showMessageDialog(
                            EDialogType.DIALOG_WITH_TEXT, title = errorTitle, dialogText = errorText
                        )
                    }, reason = 2)
                }
            })
    }
}
