package ui.screens.splash.splashStart

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dependencies.RepositoriesProvider
import dependencies.di
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.nav_settings_privacy_title
import fiori.sharedmodule.generated.resources.nav_settings_terms_title
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.models.AppVariant
import kotpref.models.AuthorizationSocial
import kotpref.models.EDialogType
import kotpref.models.NewsResult
import kotpref.utils.IDialogManager
import kotpref.utils.IPlatformInfoManager
import managers.AmplitudeEvent
import managers.AmplitudeManager
import managers.IFirebaseManager
import managers.PaywallType
import managers.analytics.AnalyticsManager
import managers.analytics.AnalyticsRegistrationEvents
import network.restApi.Endpoint
import network.socket.WebSocketManager
import org.kodein.di.instance
import ui.resources.ResManager


sealed class SplashScreenEvent {
    data object OnRegisterClick : SplashScreenEvent()
    data object OnLoginClick : SplashScreenEvent()
    data object ShowOnboardingStart : SplashScreenEvent()
    data object ShowMainPage : SplashScreenEvent()
    data class SettingsWebPage(val url: String, val title: String) : SplashScreenEvent()
}

class SplashVM(val obtainEvent: (SplashScreenEvent) -> Unit) : ViewModel() {

    private val repositoriesProvider by di.instance<RepositoriesProvider>()
    private val dialogManager by di.instance<IDialogManager>()
    private val firebaseManager by di.instance<IFirebaseManager>()
    private val amplitudeManager by di.instance<AmplitudeManager>()
    private val platformInfoManager by di.instance<IPlatformInfoManager>()

    private val accountRepository = repositoriesProvider.accountRepository
    private val chatRepository = repositoriesProvider.chatRepository


    init {
        WebSocketManager.accountSessionExpired = false
//        RequestQueue.tokenIsActual = true
        accountRepository.loadSettings()

        if (AppVariant.isWeb()) {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingWelcomeScreenShown())
            amplitudeManager.sendIdentify("location_access", "no")
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingLocationAccess("no"))
            amplitudeManager.sendEvent(AmplitudeEvent.NotificationsAboutMessages)
        }
        accountRepository.loadPaywall(PaywallType.Paywall, onSuccess = {
            val config = accountRepository.userAdaptyPaywalls.adaptyPaywallConfig
            val onboardingFlowType = config?.getOnboardingFlowType() ?: "long"
            amplitudeManager.sendIdentify(AmplitudeEvent.OnboardingType, onboardingFlowType)
            amplitudeManager.sendEvent(
                AmplitudeEvent.OnboardingWelcomeScreenShown(
                    onboardingFlowType
                )
            )
        }, onError = {
            amplitudeManager.sendEvent(AmplitudeEvent.OnboardingWelcomeScreenShown())
        })
    }


    fun continueTerms() {
        viewModelScope.launch(Dispatchers.Main) {
            val termsTitle = ResManager.getString(Res.string.nav_settings_terms_title)
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.startTermsConditionsClick.name)
            //router.route(Destination.SettingsWebPage(Endpoint.getTermsUrl(), termsTitle))
            obtainEvent(SplashScreenEvent.SettingsWebPage(Endpoint.getTermsUrl(), termsTitle))
        }
    }

    fun continuePrivacy() {
        viewModelScope.launch(Dispatchers.Main) {
            val privacyTitle = ResManager.getString(Res.string.nav_settings_privacy_title)
            AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.startPrivacyPolicyClick.name)
            //router.route(Destination.SettingsWebPage(Endpoint.getPrivacyPolicyUrl(), privacyTitle))
            obtainEvent(
                SplashScreenEvent.SettingsWebPage(Endpoint.getPrivacyPolicyUrl(), privacyTitle)
            )
        }
    }

    fun continueSignUp() {
        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.startCreateAccountClick.name)
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingWelcomeScreenSignUpClicked)
        //router.route(Destination.SplashSignUp())
        obtainEvent(SplashScreenEvent.OnRegisterClick)
    }

    fun continueSignIn() {
        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.startSignInClick.name)
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingWelcomeScreenSignInClicked)
        //router.route(Destination.SplashSignIn())
        obtainEvent(SplashScreenEvent.OnLoginClick)
    }

    fun showNews(news: NewsResult) {
        val title = news.title ?: ""
        val text = news.text ?: ""
        val button = news.button ?: ""
        dialogManager.showMessageDialog(
            EDialogType.DIALOG_NEWS, title = title, dialogText = text,
            callback = {
                //router.route(Destination.SettingsWebPage(news.url ?: "", title))
                obtainEvent(SplashScreenEvent.SettingsWebPage(news.url ?: "", title))
            }, btnOk = button
        )
    }

    fun continueFacebook(
        id: String?, token: String?, email: String?, tokenId: String?, callback: () -> Unit
    ) {
        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationFacebookClick.name)
        accountRepository.loginWithFacebook(tokenId ?: id, token, onSuccess = {
            callback()
            if (it?.info?.iamList.isNullOrEmpty() || it?.info?.interestedIn.isNullOrEmpty()) {
                accountRepository.getAppKeys().registrationByFacebook = true
                //router.route(Destination.OnBoardingStart())
                obtainEvent(SplashScreenEvent.ShowOnboardingStart)
            } else {
                repositoriesProvider.setStartValues()
                firebaseManager.init()
                chatRepository.connectWebSocket(platformInfoManager.getAppVersion())
                //router.route(Destination.MainStart())
                obtainEvent(SplashScreenEvent.ShowMainPage)
            }
        }, onError = {
            callback()
            val facebook = AuthorizationSocial(
                id = id ?: "", token = token ?: "", email = email ?: "", birthday = "",
                tokenId = tokenId,
            )

//            router.route(
//                Destination.SplashSignUpAbout(AuthorizationType.FACEBOOK, facebook)
//            )
        }, showErrorMessage = false)
    }

    fun continueGoogle(id: String?, token: String?, email: String?, callback: () -> Unit) {
        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.registrationGoogleClick.name)
        accountRepository.loginWithGoogle(id, token, onSuccess = {
            callback()
            if (it?.info?.iamList.isNullOrEmpty() || it?.info?.interestedIn.isNullOrEmpty()) {
                obtainEvent(SplashScreenEvent.ShowOnboardingStart)
            } else {
                repositoriesProvider.setStartValues()
                chatRepository.connectWebSocket(platformInfoManager.getAppVersion())
                //router.route(Destination.MainStart())
            }
        }, onError = {
            callback()
            val google = AuthorizationSocial(
                id = id ?: "", token = token ?: "", email = email ?: "", birthday = ""
            )
//            router.route(
//                Destination.SplashSignUpAbout(AuthorizationType.GOOGLE, google)
//            )
        }, showErrorMessage = false)
    }
}