package ui.screens.onboarding.paywall

import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.ui.graphics.Color
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dependencies.RepositoriesProvider
import dependencies.di
import kotlinx.coroutines.launch
import kotpref.logging.CommonLogger
import kotpref.logging.LogLvl
import kotpref.models.StripeProduct
import kotpref.models.paywall.Billings
import kotpref.utils.IDialogManager
import managers.IBillingManager
import managers.ProductDetails
import org.kodein.di.instance

sealed class PaywallScreenEvent {
    data class ShowMainPage(val clearBackStack: Boolean = false) : PaywallScreenEvent()
}

class PaywallScreenVM(
    private val viewModelCallback: (PaywallScreenEvent) -> Unit
) : ViewModel() {

    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val billingManager by di.instance<IBillingManager>()
    val dialogManager by di.instance<IDialogManager>()

    val accountRepository = repositoriesProvider.accountRepository

    val products = mutableStateListOf<ProductDetails>()
    val btnProgress = mutableStateOf(false)
    var selectedProduct: String = ""
    val selectedProductID = mutableStateOf("")
    var weekPrice = 0.0

    val showingAllFeatures = mutableStateOf(false)
    val showingOtherSubscriptions = mutableStateOf(false)

    val colorList = mutableListOf<Color>()

    val stripeClientSecret = mutableStateOf("")
    val showStripeCard = mutableStateOf(false)
    val showStripeAppleGoogle = mutableStateOf(false)
    val waitingState = mutableStateOf(false)

    val isNewDesign = mutableStateOf(true)
    val isNewHorizontalButtonDesign = mutableStateOf(false)
    val isBoxButtonDesign = mutableStateOf(false)
    val isShowCancelAnytime = mutableStateOf(false)
    val isShowBottomTotalPrice = mutableStateOf(false)
    val isReview = mutableStateOf(false)
    val isPropose = mutableStateOf(true)
    val cancelAnytimeNewStyle = mutableStateOf(false)
    val annual12MonthsText = mutableStateOf(false)
    val discountOnlyForPopularProduct = mutableStateOf(false)
    val mainButtonPulse = mutableStateOf(true)

    fun buyStripeProduct(paymentId: String?, priceID: String?, productId: String?) {
        if (paymentId.isNullOrEmpty()) {
            viewModelCallback(PaywallScreenEvent.ShowMainPage())
            return
        }
        viewModelCallback(PaywallScreenEvent.ShowMainPage())
        /*waitingState.value = true
        accountRepository.buyStripeProduct(
            priceId = priceID ?: "",
            productId = productId,
            paymentMethodId = paymentId,
            onSuccess = { data ->
                waitingState.value = false
                viewModelCallback(PaywallScreenEvent.ShowMainPage())
            }, onError = {
                waitingState.value = false
            }
        )*/
    }

    fun loadStripeClientSecret(stripeProduct: StripeProduct?) {
        if (stripeProduct == null) return
        waitingState.value = true
        viewModelScope.launch {
            accountRepository.loadStripeClientSecret(
                priceId = stripeProduct.priceId ?: "",
                productId = stripeProduct.productId,
                variationId = stripeProduct.variationId,
                onSuccess = {
                    val clientSecret = it?.data?.clientSecret ?: ""
                    stripeClientSecret.value = clientSecret
                    btnProgress.value = false
                    showStripeAppleGoogle.value = true
                    waitingState.value = false
                }, onError = {
                    setDefaultSelectedProduct()
                    btnProgress.value = false
                    waitingState.value = false
                })
        }
    }

    fun setDefaultSelectedProduct() {
        products.firstOrNull { Billings.isDiscountSubscribe(it.productDetails.productId) }?.let {
            selectedProductID.value = it.discountDetails?.productId ?: it.productDetails.productId
        }
    }

    init {
        val list = accountRepository.getPaywallButtonsColor()
        list.forEach {
            if (it.length <= 6) {
                val color = "FF$it"
                colorList.add(Color(color.toLong(16)))
            } else {
                colorList.add(Color(it.toInt(16)))
            }
        }

        val paywallConfig = accountRepository.userAdaptyPaywalls.adaptyPaywallConfig
        if (paywallConfig != null) {
            paywallConfig.getPaywallStyle()?.let {
                isNewDesign.value = false
                if (it == 2) isNewDesign.value = true
            }

            isNewHorizontalButtonDesign.value = accountRepository.paywallWithNewHorizontalButtonStyle(true)
            isBoxButtonDesign.value = paywallConfig.getPaywallShowOtherWithBoxButtons() ?: false
            isShowCancelAnytime.value = paywallConfig.getPaywallShowOtherWithCancelAnytime() ?: false
            isShowBottomTotalPrice.value = paywallConfig.getPaywallShowOtherWithBottomTotalPrice() ?: false
            isReview.value = accountRepository.settingsForAppleReview(true)
            annual12MonthsText.value = paywallConfig.getAnnual12MonthsText() ?: false
            mainButtonPulse.value = (paywallConfig.paywallButtonAnimatedStyle ?: 0) > 0
            cancelAnytimeNewStyle.value = paywallConfig.isUseCancelAnytimeNewStyle() ?: false
        }

        billingManager.getAllProductDetails { productDetails ->
            CommonLogger().log(LogLvl.DEBUG, "PaywallScreenVM", "productDetails: $productDetails")
            val weekSubscribe =
                productDetails.firstOrNull { Billings.isWeekSubscribe(it.productDetails.productId) }
            if (weekSubscribe != null) {
                val price =
                    billingManager.getSubscribePrice(weekSubscribe.productDetails.productId)?.priceAmountMicros
                weekPrice = if ((price ?: 0L) == 0L) 0.0 else price!! / 1000000.0
            } else {
                val monthSubscribe =
                    productDetails.firstOrNull { Billings.isMonthSubscribe(it.productDetails.productId) }
                val price =
                    billingManager.getSubscribePrice(monthSubscribe?.productDetails?.productId)?.priceAmountMicros
                weekPrice = if ((price ?: 0L) == 0L) 0.0 else price!! / 1000000.0
            }
            products.clear()
            val yearSubscribe =
                productDetails.firstOrNull {
                    Billings.isYearSubscribe(it.productDetails.productId) && !Billings.isDiscountSubscribe(
                        it.productDetails.productId
                    )
                }
            val yearDiscountSubscribe =
                productDetails.firstOrNull { Billings.isDiscountSubscribe(it.productDetails.productId) }
            if (yearSubscribe != null) {
                val product = ProductDetails(
                    yearSubscribe.productDetails, yearDiscountSubscribe?.productDetails
                )
                selectedProductID.value =
                    product.discountDetails?.productId ?: product.productDetails.productId
                products.add(product)
                products.addAll(productDetails.filter { !Billings.isYearSubscribe(it.productDetails.productId) })
            } else {
                products.addAll(productDetails)
                setDefaultSelectedProduct()
            }
            initPopularProduct()
        }
    }

    fun initPopularProduct() {
        val paywallConfig = accountRepository.userAdaptyPaywalls.adaptyPaywallConfig
        if (paywallConfig == null) return
        val productIds = products.map { it.discountDetails?.productId ?: it.productDetails.productId }
        var popularProductId = paywallConfig.getPaywallPopularProductId()
        if (!productIds.contains(popularProductId)) {
            popularProductId = null
        }
        val boxPopularProductId = paywallConfig.getPaywallBoxDiscountSubscription()
        if (!boxPopularProductId.isNullOrEmpty()) {
            popularProductId = boxPopularProductId
            discountOnlyForPopularProduct.value = true
        }
    }

    fun hideOtherSubscriptions() {
        val product = products.first()
        selectedProductID.value =
            product.discountDetails?.productId ?: product.productDetails.productId
        showingOtherSubscriptions.value = false
    }
}
