 */
class AccountPronounceConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountPronounce {
            var item = AccountPronounce.DO_NOT_SHOW
            enumValues<AccountPronounce>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}