fun Modifier.clipByCorner(roundedCorner: Int = 9999) = this.borderRadius(
    topLeft = roundedCorner.dp,
    topRight = roundedCorner.dp,
    bottomRight = roundedCorner.dp,
    bottomLeft = roundedCorner.dp
).overflow(Overflow.Hidden)

fun Modifier.alignCenter() = this.display(DisplayStyle.Flex)
    .justifyContent(JustifyContent.Center)
    .alignItems(AlignItems.Center)

fun Modifier.padding(
    start: CSSLengthOrPercentageNumericValue = 0.dp,
    end: CSSLengthOrPercentageNumericValue = 0.dp,
    top: CSSLengthOrPercentageNumericValue = 0.dp,
    bottom: CSSLengthOrPercentageNumericValue = 0.dp,
): Modifier = this.padding(left = start, right = end, top = top, bottom = bottom)

fun Modifier.padding(
    horizontal: CSSLengthOrPercentageNumericValue = 0.dp,
    vertical: CSSLengthOrPercentageNumericValue = 0.dp
): Modifier = this.padding(topBottom = vertical, leftRight = horizontal)

fun Modifier.clickable(
    callback: () -> Unit
): Modifier = this.cursor(Cursor.Pointer).onClick { callback.invoke() }

fun Modifier.alpha(
    alpha: Float
): Modifier = this.opacity(alpha)

fun Modifier.gradientBackground(
    colors: List<Color>,
    angle: Int = 45
) = styleModifier {
    var colorList = ""
    colors.forEachIndexed { index, color ->
        colorList += "${color}${if (index != colors.lastIndex) ", " else ""}"
    }
    backgroundImage("linear-gradient(${angle}deg, ${colorList})")
}


fun Float.toPercent() = (this * 100).percent


fun Color.copy(alpha: Float): Color = this.toRgb().copyf(alpha = alpha)

val Number.dp
    get() = (this.toDouble() / 16.0).cssRem

