@Composable
fun Modifier.onSizeChanged(
    onSizeChanged: (width: Int, height: Int) -> Unit
): Modifier {
    val latestCallback = rememberUpdatedState(onSizeChanged)

    return this.then(Modifier.attrsModifier {
        var ro: ResizeObserver? = null

        ref { element ->
            ro?.disconnect()
            ro = ResizeObserver { entries, _ ->
                entries.firstOrNull()?.contentRect?.let { rect ->
                    if (rect.width > 0.0 && rect.height > 0.0) {
                        latestCallback.value(rect.width.toInt(), rect.height.toInt())
                    } else {
                        latestCallback.value(rect.width.toInt(), rect.height.toInt())
                    }
                }
            }

            ro!!.observe(element)

            onDispose {
                ro?.disconnect()
                ro = null
            }
        }
    })
}