package kotpref.models.typeConverter.multi

import kotpref.models.account.enums.AccountRelationship
import ui.resources.ResManager


/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-16.
 */
class AccountRelationshipConverter {
    companion object {
        fun positionsToList(positions: MutableList<Int>?): MutableList<AccountRelationship>? {
            if (positions == null) return null
            val list = mutableListOf<AccountRelationship>()
            positions.forEach { item ->
                list.add(
                    AccountRelationship.entries.first { it.position == item })
            }
            return list
        }

        suspend fun stringToPositions(list: MutableList<String>?): MutableList<Int>? {
            val positions = mutableListOf<Int>()
            list?.forEach { item ->
                val relationship = AccountRelationship.entries
                    .first {
                        val resId = ResManager.getString(it.resId())
                        resId == item
                    }.position
                positions.add(relationship)
            }
            return positions
        }

        fun listToPositions(list: MutableList<AccountRelationship>?): MutableList<Int>? {
            val positions = mutableListOf<Int>()
            list?.forEach { positions.add(it.position) }
            return positions
        }
    }
}