package kotpref.models.account.single

import kotpref.models.account.enums.AccountAccommodation


/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-16.
 */
class AccountAccommodationConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountAccommodation {
            var item = AccountAccommodation.DO_NOT_SHOW
            enumValues<AccountAccommodation>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}