@Composable
fun DefaultRangeSlider(
    modifier: Modifier = Modifier.fillMaxWidth(),
    currentMinValue: Int = 18,
    currentMaxValue: Int = 60,
    minValue: Int = 18,
    maxValue: Int = 60,
    activeTrackColor: Color = JsMainTheme.colors.app_main_color,
    onProgressChange: (currentMin: Int, currentMax: Int) -> Unit = { _, _ -> }
) {
    val range = remember { mutableStateOf(currentMinValue.toFloat()..currentMaxValue.toFloat()) }
    CustomRangeSlider(
        modifier = modifier,
        range = range,
        minValue = minValue,
        maxValue = maxValue,
        activeTrackColor = activeTrackColor,
        onProgressChange = onProgressChange
    )
}

@Composable
fun CustomRangeSlider(
    modifier: Modifier = Modifier,
    range: MutableState<ClosedFloatingPointRange<Float>>,
    minValue: Int = 18,
    maxValue: Int = 60,
    thumbRadius: Int = 14,
    sliderHeight: Int = 8,
    activeTrackColor: Color = JsMainTheme.colors.app_main_color,
    inactiveTrackColor: Color = JsMainTheme.colors.text_color_gray,
    thumbColor: Color = Colors.White,
    onProgressChange: (currentMin: Int, currentMax: Int) -> Unit = { _, _ -> }
) {
    val screenSize = getJsScreenSizeInfo()
    var startValue by remember { mutableStateOf(range.value.start) }
    var endValue by remember { mutableStateOf(range.value.endInclusive) }

    LaunchedEffect(range) {
        startValue = range.value.start.coerceIn(minValue.toFloat(), maxValue.toFloat())
        endValue = range.value.endInclusive.coerceIn(minValue.toFloat(), maxValue.toFloat())
    }

    var activeThumb by remember { mutableStateOf<Boolean?>(null) }

    val canvasElement = remember { mutableStateOf<HTMLCanvasElement?>(null) }
    val canvasContext = remember { mutableStateOf<CanvasRenderingContext2D?>(null) }

    val drawSlider: (Int, Int) -> Unit = rememberUpdatedState<(Int, Int) -> Unit> { width, height ->
        val ctx = canvasContext.value ?: return@rememberUpdatedState
        val currentCanvas = canvasElement.value ?: return@rememberUpdatedState

        // Очистка Canvas
        ctx.clearRect(0.0, 0.0, width.toDouble(), height.toDouble())

        val trackHeight = sliderHeight.toDouble()
        val trackY = height / 2.0 // Центр по вертикали

        // Inactive track
        ctx.strokeStyle = inactiveTrackColor.toRgb()
        ctx.lineWidth = trackHeight
        ctx.lineCap = CanvasLineCap.ROUND
        ctx.beginPath()
        ctx.moveTo(thumbRadius.toDouble(), trackY)
        ctx.lineTo(width - thumbRadius.toDouble(), trackY)
        ctx.stroke()

        // Active track
        // Важно: Нормализация значений к диапазону 0..1, затем масштабирование к эффективной ширине Canvas
        val effectiveCanvasWidth = width - (thumbRadius * 2)
        val normalizedStart = (startValue - minValue) / (maxValue - minValue)
        val normalizedEnd = (endValue - minValue) / (maxValue - minValue)

        val startPx = normalizedStart * effectiveCanvasWidth + thumbRadius
        val endPx = normalizedEnd * effectiveCanvasWidth + thumbRadius

        ctx.strokeStyle = activeTrackColor.toRgb()
        ctx.lineWidth = trackHeight
        ctx.lineCap = CanvasLineCap.ROUND
        ctx.beginPath()
        ctx.moveTo(startPx.toDouble(), trackY)
        ctx.lineTo(endPx.toDouble(), trackY)
        ctx.stroke()

        // Thumbs
        ctx.fillStyle = thumbColor.toRgb()

        // Start thumb
        ctx.beginPath()
        ctx.arc(startPx.toDouble(), trackY, thumbRadius.toDouble(), 0.0, 2 * kotlin.math.PI)
        ctx.fill()

        // End thumb
        ctx.beginPath()
        ctx.arc(endPx.toDouble(), trackY, thumbRadius.toDouble(), 0.0, 2 * kotlin.math.PI)
        ctx.fill()
    }.value

    LaunchedEffect(
        startValue,
        endValue,
        sliderHeight,
        thumbRadius,
        screenSize
    ) {
        val canvas = canvasElement.value ?: return@LaunchedEffect
        val ctx = canvasContext.value ?: return@LaunchedEffect

        val rect = canvas.getBoundingClientRect()
        val currentWidth = rect.width.toInt()
        val currentHeight = rect.height.toInt()

        if (canvas.width != currentWidth || canvas.height != currentHeight) {
            canvas.width = currentWidth
            canvas.height = currentHeight
        }

        // Запрашиваем кадр анимации для перерисовки
        window.requestAnimationFrame {
            drawSlider(currentWidth, currentHeight)
        }
    }

    fun onEventDown(targetElement: HTMLElement, clickX: Double): Boolean? {
        val rect = targetElement.getBoundingClientRect()
        val effectiveCanvasWidth = rect.width.toFloat() - (thumbRadius * 2)
        val normalizedStart = (startValue - minValue) / (maxValue - minValue).toFloat()
        val normalizedEnd = (endValue - minValue) / (maxValue - minValue).toFloat()

        val startThumbX = normalizedStart * effectiveCanvasWidth + thumbRadius
        val endThumbX = normalizedEnd * effectiveCanvasWidth + thumbRadius

        // Увеличена область реакции для ползунков
        val grabTolerance = thumbRadius * 1.5
        val startThumbDistance = (clickX - startThumbX).absoluteValue
        val endThumbDistance = (clickX - endThumbX).absoluteValue

        // Определяем, какой ползунок ближе и находится в области захвата
        val isStartThumbGrabbed = startThumbDistance <= grabTolerance
        val isEndThumbGrabbed = endThumbDistance <= grabTolerance

        return when {
            isStartThumbGrabbed && isEndThumbGrabbed -> {
                if (endValue.toInt() == maxValue) true
                else if (startValue.toInt() == minValue) false
                else if (startThumbDistance < endThumbDistance) true
                else false
            }

            isStartThumbGrabbed -> true
            isEndThumbGrabbed -> false
            else -> null
        }
    }

    fun onEventMove(targetElement: HTMLElement, currentX: Double, preventDefault: () -> Unit) {
        val rect = targetElement.getBoundingClientRect()
        val effectiveCanvasWidth = rect.width.toFloat() - (thumbRadius * 2)
        val newValueRange = (maxValue - minValue).toFloat()

        val clampedX =
            currentX.coerceIn(thumbRadius.toDouble(), rect.width - thumbRadius)
        val value =
            ((clampedX - thumbRadius) / effectiveCanvasWidth * newValueRange + minValue.toFloat())
                .coerceIn(minValue.toDouble(), maxValue.toDouble())

        if (activeThumb == true) {
            startValue = value.coerceAtMost(endValue.toDouble()).toFloat()
        } else if (activeThumb == false) {
            endValue = value.coerceAtLeast(startValue.toDouble()).toFloat()
        }

        range.value = startValue..endValue
        onProgressChange(startValue.toInt(), endValue.toInt())
        preventDefault()
    }

    Box(modifier = modifier) {
        Box(modifier = Modifier.fillMaxSize().attrsModifier {
            onMouseDown { event ->
                val targetElement = event.currentTarget as? HTMLElement ?: return@onMouseDown
                val rect = targetElement.getBoundingClientRect()
                val clickX = event.clientX - rect.left
                activeThumb = onEventDown(targetElement, clickX)
                if (activeThumb != null) event.preventDefault()
            }

            onMouseMove { event ->
                if (activeThumb != null) {
                    val targetElement = event.currentTarget as? HTMLElement ?: return@onMouseMove
                    val rect = targetElement.getBoundingClientRect()
                    val currentX = event.clientX - rect.left
                    onEventMove(targetElement, currentX) { event.preventDefault() }
                }
            }

            onMouseUp { activeThumb = null }
            onMouseLeave { activeThumb = null }

            onTouchStart { event ->
                val targetElement = event.currentTarget as? HTMLElement ?: return@onTouchStart
                val rect = targetElement.getBoundingClientRect()
                val clickX = event.touches[0]?.clientX?.minus(rect.left) ?: return@onTouchStart
                activeThumb = onEventDown(targetElement, clickX)
                if (activeThumb != null) event.preventDefault()
            }

            onTouchMove { event ->
                if (activeThumb != null) {
                    val targetElement = event.currentTarget as? HTMLElement ?: return@onTouchMove
                    val rect = targetElement.getBoundingClientRect()
                    val currentX = event.touches[0]?.clientX?.minus(rect.left) ?: return@onTouchMove
                    onEventMove(targetElement, currentX) { event.preventDefault() }
                }
            }

            onTouchEnd { activeThumb = null }
            onTouchCancel { activeThumb = null }
        }) {
            // Drawing the slider track and thumbs
            Div(attrs = Modifier.fillMaxSize().toAttrs()) {
                DisposableEffect(Unit) {
                    val element = document.createElement("canvas") as HTMLCanvasElement
                    element.style.width = "100%"
                    element.style.height = "100%"

                    scopeElement.appendChild(element)
                    canvasElement.value = element
                    canvasContext.value = element.getContext("2d") as? CanvasRenderingContext2D

                    /*val resizeListener: (org.w3c.dom.events.Event) -> Unit = {
                        val rect = element.getBoundingClientRect()
                        element.width = rect.width.toInt()
                        element.height = rect.height.toInt()
                        drawSlider(element.width, element.height)
                    }
                    window.addEventListener("resize", resizeListener)*/


                    onDispose {
//                        window.removeEventListener("resize", resizeListener)
                        scopeElement.removeChild(element)
                        canvasElement.value = null
                        canvasContext.value = null
                    }
                }
            }
        }
    }
}


