@Composable
fun StripeByAppleGoogleScreen(
    viewModel: PaywallScreenVM,
    onPurchase: (String?, String?, String?) -> Unit,
    onError: (String) -> Unit,
    onClose: () -> Unit
) {
    val showCardInput = remember { mutableStateOf(false) }

    val selectedProductId = viewModel.selectedProductID.value
    val stripeProduct =
        BillingManager.productDetailsList.firstOrNull { it.productId == selectedProductId }


    val productInfo = ProductInfo(
        productId = selectedProductId,
        priceAmountMicros = (stripeProduct?.amount ?: 0).toLong() * 10_000L,
        priceCurrencyCode = (stripeProduct?.currency ?: "").uppercase()
    )
    val price = productInfo.priceAmountMicros / 1000000.0
    val priceCurrentCode = productInfo.priceCurrencyCode
    val priceFormat = getPriceFormat(price)
    val priceString = "$priceCurrentCode $priceFormat"

    LaunchedEffect(stripeProduct) {
        try {
            val publicKey =
                //"pk_test_51R4nCzB0QJD082mvDtI046bmpkkIGjd6fi2eHJpHrVtytwQ17ta56AzmJVnFLnOOKh5x7POVWFNTkVLVjOTZzRXd00stEknj5N"
                "pk_test_51SVqQzPsQ57FJZbuoTgaJyVgCqZIxljwO1sygtx84CIRyNnrb3oMTYp7BxWYwcn53UkuwWESPTzA9fJfC2hbDzRV00k24fJYff"
            StripeInterop.initStripe(publicKey)
            console.log("Stripe initialization success")
        } catch (e: Throwable) {
            onError("Stripe initialization error: $e")
            console.error("Stripe initialization error: $e")
        }
    }

    JsAnimatedVisibility(
        visible = viewModel.showStripeAppleGoogle.value,
        durationMs = 300,
        modifier = Modifier.fillMaxSize().zIndex(10)
    ) {
        Box(Modifier.fillMaxSize()) {
            CheckoutInfoView(
                viewModel, priceString, showCardInput,
                viewModel.stripeClientSecret, onClose,
                stripeProduct, onPurchase, onError
            )
            CardInputView(viewModel, showCardInput, stripeProduct, onPurchase)
        }
    }
}

@Composable
private fun CheckoutInfoView(
    viewModel: PaywallScreenVM,
    priceString: String,
    showCardInput: MutableState<Boolean>,
    stripeClientSecret: MutableState<String>,
    onClose: () -> Unit,
    stripeProduct: StripeProduct?,
    onPurchase: (String?, String?, String?) -> Unit,
    onError: (String) -> Unit
) {
    val applePayAvailable = remember { mutableStateOf(false) }
    val googlePayAvailable = remember { mutableStateOf(false) }

    LaunchedEffect(stripeProduct) {
        try {
            //Проверка доступности Google Pay и Apple Pay
            val urlAddress = window.location.href
            if (!AppVariant.isIos() || !(urlAddress.contains("http://") || urlAddress.contains("github.io"))) {
                val prAvailability = initStripePaymentRequest(
                    amountInCents = (stripeProduct?.amount ?: 0),
                    currency = (stripeProduct?.currency ?: "usd").lowercase(),
                    countryCode = "US",
                    label = stripeProduct?.interval ?: "",
                )
                prAvailability?.let {
                    applePayAvailable.value = it.applePay
                    googlePayAvailable.value = it.googlePay

                    if (applePayAvailable.value || googlePayAvailable.value) {
                        // Устанавливаем коллбэки для Payment Request
                        StripeInterop.setGooglePayPaymentMethodCallback { paymentMethodId ->
                            console.log("Google Pay Payment Method ID: $paymentMethodId")
                            onPurchase(
                                paymentMethodId,
                                stripeProduct?.priceId,
                                stripeProduct?.productId
                            )
                        }
                        StripeInterop.setApplePayPaymentMethodCallback { paymentMethodId ->
                            console.log("Apple Pay Payment Method ID: $paymentMethodId")
                            onPurchase(
                                paymentMethodId,
                                stripeProduct?.priceId,
                                stripeProduct?.productId
                            )
                        }
                        StripeInterop.setupPaymentRequestListeners(clientSecret = stripeClientSecret.value) // Активируем слушателей
                        console.log("Google/Apple Pay inited: googlePayAvailable = ${googlePayAvailable.value}; applePayAvailable = ${applePayAvailable.value}")
                    } else {
                        console.log("Google/Apple Pay not available")
                    }
                }
            }
        } catch (e: Throwable) {
            onError("Stripe initialization error: $e")
            console.error("Stripe initialization error: $e")
        }
    }

    Column(
        Modifier.fillMaxSize().background(Color.rgb(0x121419)).overflow(Overflow.Auto),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Box(
            Modifier.fillMaxWidth().zIndex(9),
        ) {
            Box(
                Modifier.size(48.dp).padding(start = 16.dp, top = 16.dp)
                    .clickable { onClose() },
            ) { JsImageView(Res.drawable.ic_delete_input, modifier = Modifier.size(24.dp)) }
        }

        JsImageView("ic_logo_fiorry_web", modifier = Modifier.height(36.dp))

        Column(
            Modifier.fillMaxWidth(60.percent).padding(top = 40.dp, bottom = 38.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            JsTextView(
                text = stringResource(Res.string.paywall_stripe_title_1),
                textColor = JsMainTheme.colors.text_color_white,
                textSize = 12,
                fontWeight = FontWeight.Bold
            )
            JsTextView(
                text = stringResource(Res.string.paywall_stripe_title_2),
                modifier = Modifier.padding(vertical = 2.dp),
                textColor = JsMainTheme.colors.text_color_white,
                textSize = 12,
                fontWeight = FontWeight.Bold
            )
            JsImageView("ic_paywall_stars_web", modifier = Modifier.height(16.dp))
        }

        Spacer(
            Modifier.fillMaxWidth().height(1.dp),
            params = Modifier.padding(horizontal = 20.dp).background(Colors.White.copy(0.3f))
        )

        Box(Modifier.fillMaxWidth().padding(horizontal = 20.dp)) {
            Row(Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 10.dp)) {
                JsTextView(
                    text = stringResource(Res.string.paywall_stripe_total_price),
                    modifier = Modifier.weight(1f).padding(end = 8.dp),
                    textColor = JsMainTheme.colors.text_color_white,
                    textSize = 16,
                    fontWeight = FontWeight.Bold
                )
                JsTextView(
                    text = priceString,
                    textColor = Color.rgb(0xE965C4),
                    textSize = 16,
                    fontWeight = FontWeight.Bold
                )
            }
        }


        Spacer(
            Modifier.fillMaxWidth().height(1.dp),
            params = Modifier.padding(horizontal = 20.dp).background(Colors.White.copy(0.3f))
        )

        Spacer(Modifier.height(38.dp))

        JsTextView(
            text = stringResource(Res.string.paywall_stripe_description, priceString),
            textColor = JsMainTheme.colors.text_color_white,
            textSize = 12,
            fontWeight = FontWeight.Normal,
            modifier = Modifier.fillMaxWidth().padding(horizontal = 20.dp)
        )
        Spacer(Modifier.height(38.dp))

        Row(
            Modifier.fillMaxWidth().padding(horizontal = 20.dp),
            verticalAlignment = Alignment.Top
        ) {
            Row(Modifier.weight(1f)) {
                JsImageView("ic_paywall_cancel_web", modifier = Modifier.size(24.dp))
                JsTextView(
                    text = stringResource(Res.string.paywall_stripe_cancel_anytime),
                    modifier = Modifier.weight(1f).padding(horizontal = 8.dp),
                    textColor = JsMainTheme.colors.text_color_white,
                    textSize = 14,
                    fontWeight = FontWeight.Bold
                )
            }
            Row(Modifier.weight(1f)) {
                JsImageView("ic_paywall_guarantee_web", modifier = Modifier.size(24.dp))
                JsTextView(
                    text = stringResource(Res.string.paywall_stripe_guarantee),
                    modifier = Modifier.weight(1f).padding(horizontal = 8.dp),
                    textColor = Color.rgb(0xE965C4),
                    textSize = 14,
                    fontWeight = FontWeight.Bold
                )
            }
        }

        Box(Modifier.weight(1f))

        Spacer(Modifier.height(28.dp))

        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(JsMainTheme.colors.box_subscribe_propose_backgraund_gray)
                .onClick { event -> event.stopPropagation() }
        ) {
            Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 20.dp)) {
                Spacer(Modifier.height(20.dp))

                AppleAndGooglePay(applePayAvailable, googlePayAvailable)

                if (stripeClientSecret.value.isNotEmpty()) {
                    Spacer(Modifier.height(10.dp))
                    StripeElementsPaymentView(viewModel, stripeProduct, onPurchase, onError)
                } else Box(
                    Modifier.fillMaxWidth().height(54.dp)
                        .padding(horizontal = 16.dp, vertical = 12.dp)
                        .clipByCorner()
                        .background(Color.rgb(0x056FDD))
                        .clickable {
                            showCardInput.value = true
                        },
                    contentAlignment = Alignment.Center
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        JsImageView(
                            "ic_stripe_pay_card_web",
                            modifier = Modifier.size(18.dp)
                        )

                        JsTextView(
                            text = "Debit / Credit Card",
                            textColor = JsMainTheme.colors.text_color_white,
                            textSize = 14,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }

                Spacer(Modifier.height(16.dp))
            }
        }
    }
}

@Composable
fun AppleAndGooglePay(
    applePayAvailable: MutableState<Boolean>,
    googlePayAvailable: MutableState<Boolean>
) {
    if (applePayAvailable.value) {
        Spacer(Modifier.height(10.dp))
        Box(
            Modifier.fillMaxWidth().height(54.dp)
                .padding(horizontal = 16.dp, vertical = 12.dp)
                .clipByCorner()
                .background(Color.rgb(0xFFFFFF))
                .clickable { StripeInterop.triggerPaymentRequest() },
            contentAlignment = Alignment.Center
        ) {
            JsImageView(
                "ic_stripe_pay_apple_web",
                modifier = Modifier.fillMaxHeight()
            )
        }
    }


    if (googlePayAvailable.value) {
        Spacer(Modifier.height(10.dp))
        Box(
            Modifier.fillMaxWidth().height(54.dp)
                .padding(horizontal = 16.dp, vertical = 12.dp)
                .clipByCorner()
                .background(Color.rgb(0xEEEEEE))
                .clickable { StripeInterop.triggerPaymentRequest() },
            contentAlignment = Alignment.Center
        ) {
            JsImageView(
                "ic_stripe_pay_google_web",
                modifier = Modifier.fillMaxHeight()
            )
        }
    }

    if (applePayAvailable.value || googlePayAvailable.value) {
        Spacer(Modifier.height(16.dp))
        Box(Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
            Spacer(
                Modifier.fillMaxWidth().height(1.dp),
                params = Modifier.background(Color.rgb(0xC0C0C0))
            )

            JsTextView(
                text = "OR",
                modifier = Modifier.padding(horizontal = 32.dp)
                    .background(JsMainTheme.colors.box_subscribe_propose_backgraund_gray),
                textColor = JsMainTheme.colors.text_color_white,
                textSize = 12,
            )
        }
        Spacer(Modifier.height(6.dp))
    }
}

@Composable
private fun CardInputView(
    viewModel: PaywallScreenVM, showCardInput: MutableState<Boolean>,
    stripeProduct: StripeProduct?,
    onPurchase: (String, String?, String?) -> Unit
) {
    if (showCardInput.value) Box(
        Modifier.fillMaxSize()
            .background(JsMainTheme.colors.main_color_black_transparent_50)
            .clickable { showCardInput.value = false },
        contentAlignment = Alignment.Center
    ) {
        DisposableEffect(Unit) {
            setupCardElementAndCallback(WebContainer.PaymentScreen.screenName) { paymentMethodId, errorMessage ->
                if (paymentMethodId != null) {
                    onPurchase(
                        paymentMethodId,
                        stripeProduct?.priceId,
                        stripeProduct?.productId
                    )
                } else {
                    viewModel.dialogManager.showMessageDialog(errorMessage ?: "")
                }
            }

            onDispose {
                StripeInterop.unmountCardElement()
                document.getElementById(WebContainer.PaymentScreen.screenName)?.remove()
            }
        }

        Box(
            Modifier.fillMaxWidth().padding(horizontal = 16.dp)
                .onClick { event -> event.stopPropagation() }
        ) {
            Column(
                Modifier.fillMaxWidth()
                    .padding(start = 16.dp, end = 12.dp, top = 24.dp, bottom = 16.dp)
                    .clipByCorner(24)
                    .background(JsMainTheme.colors.box_subscribe_propose_backgraund_gray)
            ) {
                Div(
                    attrs = Modifier.id(WebContainer.PaymentScreen.screenName)
                        .fillMaxWidth()
                        .padding(start = 8.dp)
                        .height(50.px)
                        .toAttrs()
                ) {

                }

                Box(
                    Modifier.fillMaxWidth().height(54.dp)
                        .padding(start = 8.dp, end = 12.dp)
                ) {
                    Box(
                        Modifier.fillMaxWidth().height(54.dp)
                            .padding(horizontal = 16.dp, vertical = 12.dp)
                            .clipByCorner()
                            .background(Color.rgb(0x056FDD))
                            .clickable {
                                StripeInterop.triggerCardPaymentMethodCreation()
                            },
                        contentAlignment = Alignment.Center
                    ) {
                        JsTextView(
                            text = stringResource(Res.string.subscribe_buy_title),
                            textColor = JsMainTheme.colors.text_color_white,
                            textSize = 14,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun StripeElementsPaymentView(
    viewModel: PaywallScreenVM,
    stripeProduct: StripeProduct?,
    onPurchase: (String?, String?, String?) -> Unit,
    onError: (String) -> Unit
) {
    DisposableEffect(Unit) {
        StripeInterop.setupPaymentElement(
            WebContainer.PaymentOtherMethods.screenName,
            viewModel.stripeClientSecret.value
        )

        onDispose {
            StripeInterop.unmountCardElement()
            document.getElementById(WebContainer.PaymentOtherMethods.screenName)?.remove()
        }
    }


    Column(
        Modifier.fillMaxWidth().padding(bottom = 16.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Div(
            attrs = Modifier.id(WebContainer.PaymentOtherMethods.screenName).fillMaxWidth()
                .toAttrs()
        )

        Spacer(Modifier.height(16.dp))

        Box(
            Modifier.fillMaxWidth().height(54.dp)
                .padding(start = 8.dp, end = 12.dp)
        ) {
            Box(
                Modifier.fillMaxWidth().height(54.dp)
                    .padding(horizontal = 16.dp, vertical = 12.dp)
                    .clipByCorner()
                    .background(Color.rgb(0x056FDD))
                    .clickable {
                        viewModel.waitingState.value = true
                        viewModel.viewModelScope.launch {
                            val result = StripeInterop.confirmPayment(false).await()

                            viewModel.waitingState.value = false
                            if (result.error != null) {
                                result.error?.let { onError(it) }
                                println("Ошибка оплаты: ${result.error}")
                            } else {
                                when (result.paymentIntent?.status) {
                                    "succeeded" -> {
                                        val paymentIntentId = result.paymentIntent?.id
                                        onPurchase(
                                            null, stripeProduct?.priceId,
                                            stripeProduct?.productId
                                        )
                                        CommonLogger().log(
                                            LogLvl.DEBUG, "Stripe",
                                            "Payment succeeded! ID: $paymentIntentId"
                                        )
                                    }

                                    else -> {
                                        CommonLogger().log(
                                            LogLvl.DEBUG, "Stripe",
                                            "Non-succeeded status: ${result.paymentIntent?.status}"
                                        )
                                    }
                                }
                            }
                        }
                    },
                contentAlignment = Alignment.Center
            ) {
                JsTextView(
                    text = stringResource(Res.string.subscribe_buy_title),
                    textColor = JsMainTheme.colors.text_color_white,
                    textSize = 14,
                    fontWeight = FontWeight.Bold
                )
            }
        }
    }
}

object StripeManager {

    fun setupCardElementAndCallback(
        elementId: String,
        onPaymentMethodCallback: (String?, String?) -> Unit
    ) {
        StripeInterop.setupCardElement(elementId, onPaymentMethodCallback)
    }

    suspend fun initStripePaymentRequest(
        amountInCents: Int,
        currency: String,
        countryCode: String,
        label: String
    ): PaymentRequestAvailability? {
        return try {
            StripeInterop.initializePaymentRequest(amountInCents, currency, countryCode, label)
                .await()
        } catch (e: dynamic) {
            console.error("Error initializing payment request: $e")
            null
        }
    }
}