package managers

class EventBusManager {

    private val subscribers = mutableMapOf<String, (BusEvent) -> Unit>()
    fun addObserver(className: String, observer: (BusEvent) -> Unit) {
        subscribers[className] = observer
    }

    fun removeObserver(className: String) {
        subscribers.remove(className)
    }

    fun postEvent(event: BusEvent) {
        subscribers.forEach { it.value(event) }
    }
}

sealed class BusEvent {
    data class ChangeMainScreenState(val uiState: String) : BusEvent()

    data object Logout : BusEvent()
}