enum class JsSplashSignUpState { START, PASSWORD, NICKNAME, BIRTHDAY }

@Composable
fun SplashSignUpNewScreen(obtainEvent: (SplashSignUpAboutEvent) -> Unit) {
    val currentState = remember { mutableStateOf(JsSplashSignUpState.START) }
    val viewModel =
        rememberJsViewModel { SplashSignUpAboutVM(AuthorizationType.EMAIL.name, null, obtainEvent) }

    val displayNameErrorText = stringResource(Res.string.auth_sign_in_incorrect_display_name)
    val birthdayErrorText = stringResource(Res.string.pick_date_age_less_18_text)
    val emailErrorText = stringResource(Res.string.auth_sign_in_incorrect_email)
    val passwordErrorText = stringResource(Res.string.error_message_sign_password_at_least)

    val containerId = "splash-sign-up-container"

    PageColumnContainer(containerId = containerId) {
        JsCustomTabBar(
            onBack = {
                jsScrollToTop(containerId)
                when (currentState.value) {

                    JsSplashSignUpState.PASSWORD -> currentState.value =
                        JsSplashSignUpState.START

                    JsSplashSignUpState.NICKNAME -> currentState.value =
                        JsSplashSignUpState.PASSWORD

                    JsSplashSignUpState.BIRTHDAY -> currentState.value =
                        JsSplashSignUpState.NICKNAME

                    else -> viewModel.back()
                }
            },
            withBackground = false
        )
        Box(modifier = Modifier.fillMaxWidth().weight(1), contentAlignment = Alignment.Center) {
            when (currentState.value) {
                JsSplashSignUpState.START ->
                    SplashSignUpStartState(viewModel, containerId, currentState, emailErrorText)

                JsSplashSignUpState.PASSWORD -> SplashSignUpPasswordState(
                    viewModel, containerId, currentState, passwordErrorText
                )

                JsSplashSignUpState.NICKNAME -> SplashSignUpNicknameState(
                    viewModel, containerId, currentState, displayNameErrorText
                )

                JsSplashSignUpState.BIRTHDAY ->
                    SplashSignUpBirthdayState(viewModel, birthdayErrorText)
            }
        }
    }

    JsAnimatedVisibility(visible = viewModel.showBirthdayPicker.value, durationMs = 500) {
        Box(
            Modifier.fillMaxSize()
                .background(color = JsMainTheme.colors.main_color_black_transparent_70)
                .clickable { viewModel.showBirthdayPicker.value = false }
        ) {
            val months = shortMonthsList()
            JsDatePickerBottomSheet(
                modifier = Modifier.align(Alignment.BottomCenter),
                doneLabel = stringResource(Res.string.nav_settings_done),
                startDate = viewModel.birthdayDate,
                onDoneClick = {
                    viewModel.onDoneClickPickerCompose(it, months) {
                        viewModel.showBirthdayPicker.value = false
                    }
                },
            )
        }
    }

    if (viewModel.showProgress.value || viewModel.showRecaptcha.value) LoadingBlockState()

    if (viewModel.showRecaptcha.value) Div(
        attrs = Modifier.fillMaxSize().id(WebContainer.CaptchaScreen.screenName).toAttrs()
    )
}

@Composable
fun SplashSignUpStartState(
    viewModel: SplashSignUpAboutVM,
    containerId: String,
    currentState: MutableState<JsSplashSignUpState>,
    emailErrorText: String
) {
    Column(Modifier.fillMaxWidth()) {
        SplashSignUpTop(
            title = stringResource(Res.string.web_sign_up_title),
            drawableId = "ic_logo",
            drawableWidth = 20,
            drawableBottomPadding = 60,
        )
        SplashSignUpBottom(
            viewModel = viewModel,
            buttonTitle = stringResource(Res.string.onboarding_propose_subscription_continue),
            textHint = stringResource(Res.string.sign_up_your_real_email),
            showTerms = true,
            value = viewModel.emailValueString.value,
            errorValue = viewModel.emailError.value,
            placeholder = stringResource(Res.string.auth_text_hint_email),
            buttonWidth = 80,
            onValueChange = {
                viewModel.emailError.value = ""
                viewModel.emailValue.value = TextFieldValue(it)
                viewModel.emailValueString.value = it
            },
            hideError = { viewModel.hideErrorByField(ErrorField.Email) },
            onClick = {
                viewModel.checkEmailOnServer(emailErrorText) {
                    jsScrollToTop(containerId)
                    currentState.value = JsSplashSignUpState.PASSWORD
                    viewModel.amplitudeManager.sendEvent(AmplitudeEvent.WebFunnelPasswordShown)
                }
            }
        )
    }
}

@Composable
fun SplashSignUpPasswordState(
    viewModel: SplashSignUpAboutVM,
    containerId: String,
    currentState: MutableState<JsSplashSignUpState>,
    passwordErrorText: String
) {
    Column(Modifier.fillMaxWidth()) {
        SplashSignUpTop(
            title = stringResource(Res.string.web_app_your_password),
            text = stringResource(Res.string.sign_up_randomly_password),
            textColor = JsMainTheme.colors.text_color_default,
            drawableId = "ic_password",
            drawableFormat = "webp",
            drawableBottomPadding = 32,
        )

        var showPassword by remember { mutableStateOf(viewModel.passwordGenerated) }
        SplashSignUpBottom(
            viewModel = viewModel,
            buttonTitle = stringResource(Res.string.onboarding_start_btn_text_next),
            value = viewModel.passwordValue.value,
            errorValue = viewModel.passwordError.value,
            placeholder = stringResource(Res.string.auth_text_hint_password),
            inputType = if (showPassword) InputType.Text else InputType.Password,
            rightIcon = if (viewModel.passwordGenerated) "ic_close_attach" else if (showPassword) "ic_password_visibility_off_web" else "ic_password_visibility_web",
            rightIconClick = {
                if (viewModel.passwordGenerated) {
                    viewModel.passwordGenerated = false
                    viewModel.passwordValue.value = ""
                }
                showPassword = !showPassword
            },
            buttonWidth = 80,
            onValueChange = {
                viewModel.passwordGenerated = false
                viewModel.passwordError.value = ""
                viewModel.passwordValue.value = it
            },
            hideError = { viewModel.hideErrorByField(ErrorField.Password) },
            onClick = {
                val passwordError = viewModel.checkPasswordError(passwordErrorText)
                if (passwordError) return@SplashSignUpBottom
                jsScrollToTop(containerId)
                currentState.value = JsSplashSignUpState.NICKNAME
                viewModel.amplitudeManager.sendEvent(AmplitudeEvent.WebFunnelNicknameShown)
            }
        )

        Spacer(Modifier.height((resultHeight.value * 0.1f).px))
    }
}


@Composable
fun SplashSignUpNicknameState(
    viewModel: SplashSignUpAboutVM,
    containerId: String,
    currentState: MutableState<JsSplashSignUpState>,
    displayNameErrorText: String
) {
    Column(Modifier.fillMaxSize()) {
        SplashSignUpTop(
            title = stringResource(Res.string.sign_up_about_nickname_title),
            text = stringResource(Res.string.sign_up_about_nickname_text),
            textColor = JsMainTheme.colors.text_color_default.copy(alpha = 0.7f),
            drawableId = "ic_sign_up_nickname_web",
            drawableFormat = "webp",
            drawableBottomPadding = 60,
            modifier = Modifier.fillMaxWidth().weight(1)
        )

        Box(modifier = Modifier.fillMaxWidth().height((resultHeight.value * 0.42).px)) {
            val nicknameManager: NicknameChangeManager by di.instance()
            val displayError =
                stringResource(Res.string.auth_sign_in_incorrect_latin_display_name)
            SplashSignUpBottom(
                viewModel = viewModel,
                buttonTitle = stringResource(Res.string.onboarding_start_btn_text_next),
                value = viewModel.nicknameValue.value,
                errorValue = viewModel.nicknameError.value,
                placeholder = stringResource(Res.string.auth_text_hint_nickname),
                boxWeight = 1f,
                onValueChange = {
                    viewModel.nicknameError.value = ""
                    nicknameManager.saveChanges(
                        it, viewModel.nicknameValue.value, callback = { value ->
                            viewModel.nicknameValue.value = value
                        },
                        onError = { viewModel.nicknameError.value = displayError }
                    )
                },
                hideError = { viewModel.hideErrorByField(ErrorField.DisplayName) },
                onClick = {
                    val displayNameError =
                        viewModel.checkDisplayNameError(displayNameErrorText)
                    if (displayNameError) return@SplashSignUpBottom
                    jsScrollToTop(containerId)
                    currentState.value = JsSplashSignUpState.BIRTHDAY
                    viewModel.amplitudeManager.sendEvent(AmplitudeEvent.WebFunnelBirthdayShown)
                }
            )
        }
    }
}

