@Composable
fun SplashSignUpTop(
    title: String = "",
    text: String = "",
    textColor: Color = JsMainTheme.colors.text_color_hint,
    drawableId: String = "",
    drawableFormat: String = "png",
    drawableWidth: Int = 40,
    drawableBottomPadding: Int = 16,
    modifier: Modifier = Modifier.fillMaxSize()
) {
    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Bottom
    ) {
        if (drawableId.isNotEmpty()) {
            JsImageView(
                drawableId,
                format = drawableFormat,
                modifier = Modifier.fillMaxWidth(drawableWidth.percent)
            )
            Box(modifier = Modifier.fillMaxWidth().height(drawableBottomPadding.dp))
        }

        JsTextView(
            text = title,
            modifier = Modifier.fillMaxWidth().padding(leftRight = 20.dp),
            textColor = JsMainTheme.colors.text_color_default,
            textSize = 24,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )
        Box(modifier = Modifier.height(32.dp))
        if (text.isNotEmpty()) {
            JsTextView(
                text = text,
                modifier = Modifier.fillMaxWidth(70.percent).padding(bottom = 32.dp),
                textColor = textColor,
                textSize = 16,
                fontWeight = FontWeight.Normal,
                textAlign = TextAlign.Center
            )
        }
    }
}

@Composable
fun SplashSignUpBottom(
    viewModel: SplashSignUpAboutVM,
    buttonTitle: String,
    textHint: String = "",
    value: String,
    errorValue: String,
    placeholder: String,
    showTerms: Boolean = false,
    readOnly: Boolean = false,
    inputType: InputType<String> = InputType.Text,
    rightIcon: String? = null,
    rightIconClick: (() -> Unit)? = null,
    boxWeight: Float = 0f,
    buttonWidth: Int = 70,
    onValueChange: (String) -> Unit,
    hideError: () -> Unit,
    onTextFieldClick: (() -> Unit)? = null,
    onClick: () -> Unit,
) {
    Column(
        modifier = Modifier.fillMaxSize(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {

        JsOutlinedTextField(
            value = value,
            textSize = 14,
            textMinHeight = 50,
            placeholder = placeholder,
            readOnly = readOnly,
            isError = errorValue.isNotEmpty(),
            errorText = errorValue,
            modifier = Modifier.fillMaxWidth(80.percent)
                .onFocusIn { hideError.invoke() },
            inputType = inputType,
            rightIcon = rightIcon,
            rightIconClick = rightIconClick,
            onValueChange = onValueChange,
            onClick = onTextFieldClick
        )

        if (textHint.isNotEmpty()) {
            Box(modifier = Modifier.height(20.dp))
            JsAutoResizeText(
                text = textHint,
                modifier = Modifier
                    .fillMaxWidth(70.percent),
                color = JsMainTheme.colors.text_color_gray_sign_in,
                minTextSize = 10,
                maxTextSize = 12,
                fontWeight = FontWeight.Normal,
                textAlign = TextAlign.Center,
                maxLines = 3
            )
        }
        Box(modifier = Modifier.weight(boxWeight).minHeight(30.dp))


        SplashFiorryButton(
            title = buttonTitle,
            buttonWidth = buttonWidth
        ) { onClick.invoke() }
        if (showTerms) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(topBottom = 20.dp),
                horizontalArrangement = Arrangement.Center
            ) {
                JsTextView(
                    text = stringResource(Res.string.auth_start_group_text_sign_in),
                    textColor = JsMainTheme.colors.text_color_white,
                    textSize = 15,
                    fontWeight = FontWeight.Medium,
                    textAlign = TextAlign.Center
                )
                JsTextView(
                    text = stringResource(Res.string.auth_sign_in),
                    modifier = Modifier
                        .padding(leftRight = 16.dp)
                        .clickable {
                            viewModel.onSignInClick()
                        },
                    textColor = JsMainTheme.colors.app_main_color,
                    textSize = 15,
                    fontWeight = FontWeight.Medium,
                    textAlign = TextAlign.Center
                )
            }

            TermsAndPrivacy()
        }
        Box(modifier = Modifier.height(26.dp))
    }
}

@Composable
fun TermsAndPrivacy() {
    val terms = stringResource(Res.string.auth_start_group_terms)
    val privacy = stringResource(Res.string.auth_start_group_privacy)
    val fullText = stringResource(Res.string.auth_start_group_full_text, terms, privacy)
    val textColor = JsMainTheme.colors.text_color_gray_sign_in

    val clickableModifier = Modifier.styleModifier {
        //fontSize(getMaxMinSize(12).max.cssRem)
        color(textColor)
        fontWeight(FontWeight.Bold)
        whiteSpace("pre-wrap")
        //textDecorationLine(TextDecorationLine.Underline)
        overflow(Overflow.Hidden)
        textAlign(TextAlign.Center)
    }

    val termsModifier = clickableModifier.clickable {
        val webBrowserManager by di.instance<WebBrowserManager>()
        webBrowserManager.showWebPage(Endpoint.getTermsUrl())
    }

    val privacyModifier = clickableModifier.clickable {
        val webBrowserManager by di.instance<WebBrowserManager>()
        webBrowserManager.showWebPage(Endpoint.getPrivacyPolicyUrl())
    }

    val termsStartIndex = fullText.indexOf(terms)
    val privacyStartIndex = fullText.indexOf(privacy)
    val annotatedString = listOf(
        AnnotatedString(fullText.substring(0, termsStartIndex), null),
        AnnotatedString(
            fullText.substring(termsStartIndex, termsStartIndex + terms.length),
            termsModifier
        ),
        AnnotatedString(
            fullText.substring(termsStartIndex + terms.length, privacyStartIndex),
            null
        ),
        AnnotatedString(
            fullText.substring(privacyStartIndex, privacyStartIndex + privacy.length),
            privacyModifier
        ),
        AnnotatedString(
            fullText.substring(privacyStartIndex + privacy.length), null
        ),
    )
    JsAnnotatedStringsText(
        annotatedStrings = annotatedString,
        textSize = 12,
        textColor = JsMainTheme.colors.text_color_gray_sign_in,
        modifier = Modifier
            .fillMaxWidth(80.percent)
            .minHeight(36.dp),
        textAlign = TextAlign.Center
    )
}