import fiori.sharedmodule.generated.resources.ic_compatibility_category_habits
import fiori.sharedmodule.generated.resources.ic_compatibility_category_lifestyle
import fiori.sharedmodule.generated.resources.ic_compatibility_category_mindset
import fiori.sharedmodule.generated.resources.ic_compatibility_category_sexual
