import web.views.JsImagePreloaderQueue
import web.views.LoadingState
import web.views.OnBoardingDefaultBox
import web.views.PageContainer

@Composable
fun JsOnBoardingCompatibilityScreen(
    viewModelCallback: (OnBoardingCompatibilityEvent) -> Unit,
    viewModel: OnboardingCompatibilityVM = rememberJsViewModel {
        OnboardingCompatibilityVM(viewModelCallback)
    }
) {
    JsImagePreloaderQueue.addToQueue(
        listOf(
            "${Res.drawable.ic_compatibility_category_lifestyle.getDrawableIdName()}.png",
            "${Res.drawable.ic_compatibility_category_sexual.getDrawableIdName()}.png",
            "${Res.drawable.ic_compatibility_category_mindset.getDrawableIdName()}.png",
            "${Res.drawable.ic_compatibility_category_goals.getDrawableIdName()}.png",
            "${Res.drawable.ic_compatibility_category_habits.getDrawableIdName()}.png",

            "${Res.drawable.bg_onboarding_tutorial_first_page.getDrawableIdName()}.webp",
            "${Res.drawable.bg_onboarding_tutorial_second_page.getDrawableIdName()}.webp",
            "${Res.drawable.bg_onboarding_tutorial_third_page.getDrawableIdName()}.webp",

            "${Res.drawable.bg_finish_page_with_compatibility.getDrawableIdName()}.webp",
            "${Res.drawable.bg_finish_page.getDrawableIdName()}.webp",

            "${Res.drawable.bg_propose_subscription_new.getDrawableIdName()}.png",
            "${Res.drawable.bg_propose_subscription_middle_level.getDrawableIdName()}.webp",
            "${Res.drawable.ic_propose_subscription_logo_new.getDrawableIdName()}.webp",
            "${Res.drawable.bg_propose_subscribe_settings.getDrawableIdName()}.webp",
            "${Res.drawable.ic_subscribe_propose_have.getDrawableIdName()}.png",
            "${Res.drawable.ic_subscribe_do_not_have.getDrawableIdName()}.png",
        )
    )

    PageContainer {
        val text = viewModel.text.value
        if (text.isEmpty()) {
            LoadingState()
        } else OnBoardingDefaultBox(
            image = ResManager.drawable.bg_onboarding_compatibility,
            imageFormat = "webp",
            backButtonVisibility = viewModel.backButtonVisibility.value,
            title = stringResource(resource = Res.string.onboarding_compatibility_title),
            text = text,
            textColor = Color.rgb(0X9CADBA),
            buttonText = viewModel.buttonText.value,
            compatibilityText = stringResource(resource = Res.string.onboarding_compatibility_text_answers),
            skipText = stringResource(resource = Res.string.onboarding_compatibility_skip),
            mainButtonClick = { viewModel.startCompatibility() },
            backButtonClick = { viewModel.back() },
            skipButtonClick = { viewModel.skipCompatibility() }
        )
    }
}
