package dependencies

import kotpref.utils.IImageUtils
import kotpref.models.account.AccountNotifications
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.eventBus.EventBusManager
import kotpref.eventBus.StartRatingTimer
import kotpref.models.typeConverter.DateTimeConverterPlatform
import kotpref.stores.IAppKeysStorage
import kotpref.utils.IDialogManager
import storage.IDatabase

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-18.
 */
data class RepositoriesProvider(
    val accountRepository: AccountRepository,
    val fileRepository: FileRepository,
    val chatRepository: ChatRepository,
    val appKeys: IAppKeysStorage,
    val dialogManager: IDialogManager,
    val imageUtils: IImageUtils,
    val database: IDatabase
) {

    fun loadStartInfo(updateNotifications: (AccountNotifications) -> Unit) {
        accountRepository.loadWowUsers()
        accountRepository.getLimitsByGenders()
        accountRepository.loadQuestions()
        accountRepository.loadSettings()
        CoroutineScope(Dispatchers.Main).launch {
            val notification = accountRepository.getMyNotifications()
            if (notification == null) accountRepository.loadAccountNotification {
                updateNotifications.invoke(it)
            } else updateNotifications.invoke(notification)
        }
    }

    fun setStartValues() {
        appKeys.userBirthday = 0L
        appKeys.feedbackStartTime = DateTimeConverterPlatform.dateToString()
        appKeys.feedbackStartSessionTime = DateTimeConverterPlatform.dateToString()
        EventBusManager.post(StartRatingTimer())
    }
}