@Composable
fun PageContainer(withBackground: Boolean = true, content: @Composable (BoxScope.() -> Unit)) {
    var modifier = Modifier.fillMaxSize().styleModifier {
        property("overflow-x", "hidden")
        property("overflow-y", "auto")
    }
    if (withBackground) modifier = modifier.background(JsMainTheme.colors.main_color_background)
    Box(modifier) {
        Box(Modifier.fillMaxWidth().minHeight(resultHeight.value.px)) {
            content.invoke(this)
        }
    }
}

@Composable
fun PageColumnContainer(
    withBackground: Boolean = true,
    containerId: String? = null,
    content: @Composable (ColumnScope.() -> Unit)
) {
    var modifier = Modifier.fillMaxSize().styleModifier {
        property("overflow-x", "hidden")
        property("overflow-y", "auto")
    }
    if (!containerId.isNullOrEmpty()) modifier = modifier.id(containerId)
    if (withBackground) modifier = modifier.background(JsMainTheme.colors.main_color_background)
    Box(modifier) {
        Column(Modifier.fillMaxWidth().minHeight(resultHeight.value.px)) {
            content.invoke(this)
        }
    }
}

@Composable
fun JsDividerLine(
    modifier: Modifier = Modifier, background: Color = JsMainTheme.colors.color_dividing_line
) {
    Box(
        modifier = modifier
            .fillMaxWidth()
            .height(1.dp)
            .background(background)
    )
}

@Composable
fun Spacer(modifier: Modifier = Modifier, params: Modifier = Modifier) {
    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        Box(modifier = modifier.then(params))
    }
}


@Composable
fun JsCustomTabBar(
    onBack: () -> Unit,
    withBackground: Boolean = true,
    isColor: Boolean = true,
    tabBarType: TabBars = TabBars.EmptyTabBar,
) {
    Column(Modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(56.dp)
                .background(if (withBackground) JsMainTheme.colors.main_color_header else Colors.Transparent)
        ) {
            Box(Modifier.padding(top = 16.dp, left = 16.dp)) {
                TabBarBackArrow(onBack)
            }

            when (tabBarType) {
                is TabBars.TabBarWithRightButton -> {
                    Box(modifier = Modifier.weight(1f))
                    TabBarTextButton(
                        title = tabBarType.rightButtonTitle,
                        underline = tabBarType.rightButtonUnderline,
                        isColor = isColor,
                        onClick = tabBarType.onRightButtonClick
                    )
                }

                is TabBars.TabBarWithRightIconButton -> {
                    Box(modifier = Modifier.weight(1f))
                    JsImageView(
                        Res.drawable.ic_back_arrow/*"ic_back_arrow_web"*/,
                        Modifier.size(16.dp)
                    )
                }

                else -> {}
            }
        }

        if (withBackground) JsDividerLine(background = JsMainTheme.colors.main_color_background)
    }
}


@Composable
fun TabBarWithCenterTitle(
    title: String,
    rightButtonTitle: String,
    isColor: Boolean = true,
    isSingleLine: Boolean = false,
    showBackButton: Boolean = true,
    onBack: () -> Unit,
    rightButtonClick: () -> Unit = {}
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(56.dp)
            .background(JsMainTheme.colors.main_color_header)
    ) {
        val titlePadding = remember { mutableStateOf(0) }
        JsTextView(
            title, 20,
            Modifier
                .align(Alignment.Center)
                .padding(start = titlePadding.value.dp, end = titlePadding.value.dp),
            FontWeight.Medium,
            JsMainTheme.colors.text_color_default,
            maxLines = if (isSingleLine) 1 else null
        )

        if (showBackButton) {
            Box(Modifier.padding(top = 16.dp, left = 16.dp)) {
                TabBarBackArrow(onBack)
            }
        }

        TabBarTextButton(
            modifier = Modifier.align(Alignment.CenterEnd).onSizeChanged { width, height ->
                if (rightButtonTitle.isNotEmpty()) titlePadding.value = width
            },
            title = rightButtonTitle,
            isColor = isColor,
            onClick = rightButtonClick
        )
    }
}

@Composable
fun TabBarBackArrow(onBack: () -> Unit) {
    Box(
        Modifier
            .size(36.dp)
            .clipByCorner(18)
            .alignCenter()
            .background(Color.rgb(0X282B30))
            .clickable { onBack() }
    ) {
        JsImageView(
            Res.drawable.ic_back_arrow/*"ic_back_arrow_web"*/,
            Modifier.size(16.dp)
        )
    }
}


@Composable
fun TabBarTextButton(
    modifier: Modifier = Modifier,
    title: String,
    isColor: Boolean,
    underline: Boolean = false,
    onClick: (() -> Unit)
) {
    Box(
        contentAlignment = Alignment.Center,
        modifier = modifier
            .fillMaxHeight()
            .clickable { onClick.invoke() }) {
        JsTextView(
            title,
            textColor = if (isColor) JsMainTheme.colors.app_main_color else JsMainTheme.colors.text_color_blue_light,
            textDecoration = if (underline) TextDecorationLine.Underline else TextDecorationLine.None,
            textSize = 15,
            fontWeight = if (isColor) FontWeight.Bold else FontWeight.Normal,
            modifier = Modifier.padding(horizontal = 16.dp)
        )
    }
}


@Composable
fun MainButton(
    text: String,
    arrowIsVisible: Boolean = false,
    alpha: Float = 1f,
    enabled: Boolean = true,
    onClick: () -> Unit
) {
    val startColor: Color = JsMainTheme.colors.gradient_main_button_start
    val endColor: Color = JsMainTheme.colors.gradient_main_button_end
    val gradientAngle = 300

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(50.dp)
            .alpha(alpha)
            .clickable { if (enabled) onClick() },
        contentAlignment = Alignment.Center
    ) {
        Box(
            modifier = Modifier.fillMaxSize().gradientBackground(
                listOf(startColor.toRgb(), endColor.toRgb()), gradientAngle
            )
        )
        JsTextView(
            text = text,
            textSize = 16,
            textColor = Colors.White,
            fontWeight = FontWeight.Medium,
        )
        if (arrowIsVisible) {
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.CenterEnd
            ) {
                JsImageView(
                    Res.drawable.ic_arrow_right,
                    modifier = Modifier
                        .fillMaxHeight()
                        .padding(end = 48.dp)
                        .size(20.dp)
                )
            }
        }
    }
}

enum class AnimationDirection {
    BOTTOM_TO_TOP,
    RIGHT_TO_LEFT,
}

@Composable
fun JsAnimatedVisibility(
    visible: Boolean,
    animationDirection: AnimationDirection = AnimationDirection.BOTTOM_TO_TOP,
    durationMs: Long = 300L,
    hiddenDurationMs: Long = 300L,
    initialOffset: Int = 100,
    minOpacity: Float = 0f,
    transformAnimation: AnimationTimingFunction = AnimationTimingFunction.EaseInOut,
    opacityAnimation: AnimationTimingFunction = AnimationTimingFunction.EaseInOut,
    modifier: Modifier = Modifier.fillMaxSize(),
    content: @Composable () -> Unit
) {
    var shouldBeInComposition by remember { mutableStateOf(visible) }

    val hiddenTransformValue = remember(animationDirection, initialOffset) {
        when (animationDirection) {
            AnimationDirection.BOTTOM_TO_TOP -> "translateY(${initialOffset}%)"
            AnimationDirection.RIGHT_TO_LEFT -> "translateX(${initialOffset}%)"
        }
    }
    val visibleTransformValue = remember(animationDirection) {
        when (animationDirection) {
            AnimationDirection.BOTTOM_TO_TOP -> "translateY(0%)"
            AnimationDirection.RIGHT_TO_LEFT -> "translateX(0%)"
        }
    }


    val animatedTransform = remember { mutableStateOf(hiddenTransformValue) }
    val animatedOpacity = remember { mutableStateOf(minOpacity) }

    LaunchedEffect(visible) {
        if (visible) {
            shouldBeInComposition = true
            println("JsAnimatedVisibility shouldBeInComposition = true")
            delay(50)
            animatedTransform.value = visibleTransformValue
            animatedOpacity.value = 1f
        } else {
            animatedTransform.value = hiddenTransformValue
            animatedOpacity.value = minOpacity

            println("JsAnimatedVisibility hiddenTransformValue")
            delay(hiddenDurationMs)
            shouldBeInComposition = false
            println("JsAnimatedVisibility shouldBeInComposition = false")
        }
    }


    if (shouldBeInComposition) {
        val duration = if (visible) durationMs else hiddenDurationMs
        println("JsAnimatedVisibility InComposition duration = $duration")
        Box(
            modifier = modifier.styleModifier {
                property("opacity", animatedOpacity.value.toString())
                property("transform", animatedTransform.value)
            }.transition(
                listOf(
                    Transition.of("opacity", duration.ms, opacityAnimation),
                    Transition.of("transform", duration.ms, transformAnimation)
                )
            )
        ) { content() }
    }
}