    ///region convert From
    suspend fun convertFromIam(): MutableList<String> {
        val result = mutableListOf<String>()
        AccountIamConverter.positionsToList(account?.info?.iamList)?.forEach {
            result.add(it.resId().getString())
        }
        return result
    }

    suspend fun convertFromInterest(): MutableList<String> {
        val result = mutableListOf<String>()
        AccountIamConverter.positionsToList(account?.info?.interestedIn)?.forEach {
            result.add(it.secondResId().getString())
        }
        return result
    }

    suspend fun convertFromSex(): MutableList<String> {
        val result = mutableListOf<String>()
        if (AccountSexPositionConverter.positionsToItem(account?.info?.sexPosition) == AccountSexPosition.DO_NOT_SHOW) return result
        result.add(
            AccountSexPositionConverter.positionsToItem(account?.info?.sexPosition).resId()
                .getString()
        )
        return result
    }

    suspend fun convertFromLooking(): MutableList<String> {
