enum class SocketEvent(var event: String) {

    Subscribe("subscribe"),
    BlockAccount("block-account"),
    BanAccount("account-banned"),
    BanAccountPermanent("account-permanent-banned"),
    RetrySendMessage("retrySendMessage"),
    ReconnectWebSocket("reconnectWebSocket"),
    NextMessage("nextMessage"),
    CloseWebSocket("closeWebSocket"),
    AccountSessionExpired("account-session-expired"),


    Message("message"),
    Gift("gift"),
    ReadMessages("read-messages"),
    CreatingMessage("creating-message"),
    StartDeleteMessageTimer("start-delete-message-timer"),
    DeleteMessage("delete-message"),
    ClearHistory("clear-history"),
    DeleteChat("delete-chat"),

    GetChat("get-chat"),
    CreateRequest("request"),

    Wow("wow"),
    ViewWows("view-wows"),

    Session("session"),

    AccountConnected("account-connected"),
    AccountDelete("delete-account"),
    AccountDisconnected("account-disconnected"),

    News("news"),
    TryTrial("try-trial");

    fun getResponse(): String {
        return "${this.event}:response"
    }
}