package kotpref

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-12-23.
 */
class DelayedActionExecutor {
    var scope: CoroutineScope? = null
    var runnable: () -> Unit = { }
    var delayTimeValue: Long = 0L

    private var job: Job? = null

    constructor(delayTime: Long, listener: () -> Unit, coroutineScope: CoroutineScope = CoroutineScope(Dispatchers.Main)) {
        delayTimeValue = delayTime
        scope = coroutineScope
        runnable = listener
    }

    constructor(listener: () -> Unit, delayTime: Long = 10L) {
        CoroutineScope(Dispatchers.Main).launch {
            delay(delayTime)
            listener.invoke()
        }
    }

    fun start(delay: Long = delayTimeValue) {
        job?.cancel()
        job = scope?.launch {
            delay(delay)
            runnable.invoke()
        }
    }

    fun pause() {
        job?.cancel()
    }

}