package web

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.css.ScrollBehavior
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxHeight
import com.varabyte.kobweb.compose.ui.modifiers.scrollBehavior
import com.varabyte.kobweb.core.App
import com.varabyte.kobweb.silk.SilkApp
import com.varabyte.kobweb.silk.init.InitSilk
import com.varabyte.kobweb.silk.init.InitSilkContext
import com.varabyte.kobweb.silk.init.registerStyleBase
import com.varabyte.kobweb.silk.theme.colors.ColorMode
import com.varabyte.kobweb.silk.theme.colors.loadFromLocalStorage
import com.varabyte.kobweb.silk.theme.colors.systemPreference
import dependencies.WebDependencies
import dependencies.di
import kotlinx.browser.window
import kotpref.models.WebAppVariant
import kotpref.stores.IAppKeysStorage
import org.jetbrains.compose.resources.StringResource
import org.kodein.di.instance
import ui.resources.IResStringManager
import ui.resources.ResManager
import web.helpers.ActualAppStrings
import web.helpers.ActualAppStrings.currentAppLanguageCode
import web.theme.JsMainAppTheme

private const val COLOR_MODE_KEY = "web:colorMode"

@InitSilk
fun initColorMode(ctx: InitSilkContext) {
    ctx.config.initialColorMode =
        ColorMode.loadFromLocalStorage(COLOR_MODE_KEY) ?: ColorMode.systemPreference
}

@InitSilk
fun initStyles(ctx: InitSilkContext) {
    ctx.stylesheet.apply {
        registerStyleBase("html, body") { Modifier.fillMaxHeight() }
        registerStyleBase("body") { Modifier.scrollBehavior(ScrollBehavior.Smooth) }
    }
}

@App
@Composable
fun AppEntry(content: @Composable () -> Unit) {
    WebAppVariant.init()
    ResManager.stringManager = object : IResStringManager {
        override fun getPlatformString(resId: StringResource): String {
            return ActualAppStrings.get(resId.key)
        }

        override fun getPlatformString(resId: StringResource, formatArgs: Array<String>): String {
            return ActualAppStrings.formatString(
                ActualAppStrings.get(resId.key), args = formatArgs
            )
        }
    }
    WebDependencies()
    initAppLanguage()
    SilkApp {
        JsMainAppTheme {
            content()
        }
    }
}

fun initAppLanguage() {
    val userLanguage = window.navigator.language // example: "en-US", "pt-PT"
    val baseLanguage = userLanguage.substringBefore("-") // "en", "pt" ...

    val appKeys by di.instance<IAppKeysStorage>()
    var locale = appKeys.defaultLocale
    if (locale.isEmpty()) {
        appKeys.defaultLocale = baseLanguage
        locale = baseLanguage
    }
    currentAppLanguageCode.value = locale
}
