@Composable
fun ProfileSelectPhotosItemJs(
    index: Int,
    photo: AccountPhoto?,
    selectedPhotoIndex: Int?,
    showAddPhoto: Boolean,
    addPhotoClick: () -> Unit,
    longPhotoClick: (String) -> Unit,
    deletePhotoClick: (String) -> Unit,
    rollBack: (String) -> Unit,
) {
    val borderColor = if (showAddPhoto) JsMainTheme.colors.app_main_color else JsMainTheme.colors.top_bar_switch_background
    val boxModifier = Modifier
        .fillMaxSize()
        .aspectRatio(1/1.2)
        .border(1.dp, LineStyle.Solid, color = borderColor)
        .background(
            color = JsMainTheme.colors.main_color_background,
        )
        .clipByCorner(10)

    Box(
        modifier = boxModifier,
        contentAlignment = Alignment.Center
    ) {
        val itemNumber = index + 1
        ProfileSelectPhotosItemContentJs(
            modifier = Modifier.fillMaxSize(),
            photoUrl = photo?.url ?: "",
            selectedPhotoIndex = selectedPhotoIndex,
            itemNumber = "$itemNumber",
            showAddPhoto = showAddPhoto,
            addPhotoClick = addPhotoClick,
            onPhotoClick = longPhotoClick,
            deletePhotoClick = deletePhotoClick,
            rollbackPhoto = rollBack
        )
    }
}

@Composable
fun ProfileSelectPhotosItemContentJs(
    modifier: Modifier = Modifier,
    photoUrl: String?,
    selectedPhotoIndex: Int?,
    itemNumber: String,
    showAddPhoto: Boolean,
    addPhotoClick: () -> Unit,
    onPhotoClick: (String) -> Unit,
    deletePhotoClick: (String) -> Unit,
    rollbackPhoto: (String) -> Unit,
) {
    val imageLoaded = remember { mutableStateOf(false) }

    Box(modifier = modifier) {

        AsyncImageJs(
            src = photoUrl ?: "",
            modifier = Modifier.fillMaxSize().clickable {
                if  (showAddPhoto) addPhotoClick.invoke()
            }.onDoubleClick { onPhotoClick.invoke(photoUrl ?: "") },
            onLoading = {
                LoadingState()
            },
            onError = {
                if (showAddPhoto) {
                    Box(
                        modifier = Modifier.fillMaxSize().clickable {
                            addPhotoClick.invoke()
                        },
                        contentAlignment = Alignment.Center
                    ) {
                        JsImageViewTint(
                            drawableId = "ic_plus_gray",
                            modifier = Modifier.size(26.percent).align(Alignment.Center),
                            tintColor = JsMainTheme.colors.app_main_color,
                            contentScale = ContentScale.FillWidth
                        )
                    }
                }
            },
            onSuccess = {
                imageLoaded.value = true
            }
        )

        if (imageLoaded.value && !photoUrl.isNullOrEmpty()) {
            Box(
                modifier = Modifier
                    .size(32.dp)
                    .padding(7.dp)
                    .background(color = JsMainTheme.colors.app_main_color)
                    .clipByCorner(16)
                    .align(Alignment.TopEnd)
                    .clickable {
                        if (selectedPhotoIndex == null) {
                            deletePhotoClick.invoke(photoUrl ?: "")
                        }
                    },
                contentAlignment = Alignment.Center
            ) {
                JsImageView("ic_close_white_24dp", modifier = Modifier.size(12.dp))
            }
        }

        if (itemNumber.toInt() == 1) {
            Box(
                modifier = Modifier.fillMaxWidth().align(Alignment.BottomCenter)
                    .background(JsMainTheme.colors.people_profile_main_page_bg),
                contentAlignment = Alignment.CenterEnd
            ) {
                JsTextView(
                    text = stringResource(Res.string.people_profile_main_photo),
                    modifier = Modifier.padding(top = 4.dp, right = 8.dp, bottom = 4.dp),
                    fontWeight = FontWeight.Medium,
                    textSize = 12
                )
            }
        } else {
            Box(
                modifier = Modifier
                    .size(24.px)
                    .margin(7.px)
                    .background(color = JsMainTheme.colors.app_main_color)
                    .clipByCorner(16)
                    .align(Alignment.BottomEnd),
                contentAlignment = Alignment.Center
            ) {
                JsTextView(
                    text = itemNumber,
                    textSize = 14
                )
            }
        }

        if (imageLoaded.value && selectedPhotoIndex != null && selectedPhotoIndex != itemNumber.toInt() - 1) {
            Box(
                modifier = Modifier.fillMaxSize()
                    .background(color = JsMainTheme.colors.main_color_black_transparent_70)
                    .clickable {
                        rollbackPhoto.invoke(photoUrl ?: "")
                    },
                contentAlignment = Alignment.Center
            ) {
                JsImageView(
                    drawableId = "ic_rollback",
                    modifier = Modifier.fillMaxWidth(26.percent).align(Alignment.Center),
                    tintColor = JsMainTheme.colors.app_main_color,
                    contentScale = ContentScale.FillWidth
                )
            }
        }
    }
}