class EmailValid {
    companion object {

        fun isEmailValid(email: String): Boolean {
            return email.trim().matches(emailAddressRegex)
        }

        val emailAddressRegex = Regex(
            "[a-zA-Z0-9+._%-]{1,256}" +
                    "@" +
                    "[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,62}[a-zA-Z0-9])?" +
                    "(" +
                    "\\." +
                    "[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,62}[a-zA-Z0-9])?" +
                    ")+"
        )
    }
}