 */
class AccountKidsConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountKids {
            var item = AccountKids.DO_NOT_SHOW
            enumValues<AccountKids>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}