package web.screens.profile.profilePhotosSelect

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.toAttrs
import org.jetbrains.compose.web.css.AlignItems
import org.jetbrains.compose.web.css.DisplayStyle
import org.jetbrains.compose.web.css.JustifyContent
import org.jetbrains.compose.web.css.alignItems
import org.jetbrains.compose.web.css.display
import org.jetbrains.compose.web.css.gap
import org.jetbrains.compose.web.css.gridTemplateColumns
import org.jetbrains.compose.web.css.justifyContent
import org.jetbrains.compose.web.css.px
import org.jetbrains.compose.web.dom.Div

@Composable
fun CustomVerticalGridLayoutJs(
    columns: Int,
    horizontalSpacing: Int,
    verticalSpacing: Int,
    contentAlignment: Alignment = Alignment.TopStart,
    modifier: Modifier = Modifier,
    content: @Composable CustomGridScopeJs.() -> Unit
) {
    val items = mutableListOf<GridItem>()
    items.clear()

    val scope = object : CustomGridScopeJs {
        override fun item(
            spanX: Int,
            spanY: Int,
            modifier: Modifier,
            content: @Composable () -> Unit
        ) {
            items.add(GridItem(spanX, spanY, modifier, content))
        }
    }

    content(scope)

    Div  (
         modifier
             .toAttrs {
                 style {
                     display(DisplayStyle.Grid)
                     gridTemplateColumns("repeat($columns, 1fr)")
                     gap(verticalSpacing.px, horizontalSpacing.px)
                 }
             }
    ) {
        items.forEach { item ->
            Div(
                attrs = item.modifier.toAttrs {
                    style {
                        property("grid-column", "span ${item.spanX}")
                        property("grid-row", "span ${item.spanY}")
                        display(DisplayStyle.Flex)
                        justifyContent(
                            when (contentAlignment) {
                                Alignment.TopStart, Alignment.CenterStart, Alignment.BottomStart -> JustifyContent.FlexStart
                                Alignment.TopCenter, Alignment.Center, Alignment.BottomCenter -> JustifyContent.Center
                                else -> JustifyContent.FlexEnd
                            }
                        )
                        alignItems(
                            when (contentAlignment) {
                                Alignment.TopStart, Alignment.TopCenter, Alignment.TopEnd -> AlignItems.FlexStart
                                Alignment.CenterStart, Alignment.Center, Alignment.CenterEnd -> AlignItems.Center
                                else -> AlignItems.FlexEnd
                            }
                        )
                    }
                }
            ) {
                item.content()
            }
        }
    }
}

interface CustomGridScopeJs {
    fun item(
        spanX: Int = 1,
        spanY: Int = 1,
        modifier: Modifier = Modifier,
        content: @Composable () -> Unit
    )
}

private data class GridItem(
    val spanX: Int,
    val spanY: Int,
    val modifier: Modifier,
    val content: @Composable () -> Unit
)