@Composable
fun JsCancelAnytimeContent(tintColor: Color = Color.rgb(0xA660EB), bottomPadding: Int = 20) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .padding(start = 16.dp, end = 16.dp, bottom = bottomPadding.dp),
        contentAlignment = Alignment.Center
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            JsImageView(
                Res.drawable.ic_subscribe_cancel_anytime,
                tintColor = tintColor,
                modifier = Modifier.size(22.dp)
            )
            Spacer(modifier = Modifier.width(6.dp))
            JsTextView(
                stringResource(Res.string.onboarding_subscription_cancel_anytime), 15,
                textColor = tintColor
            )
        }
    }
}