package web.pages

import androidx.compose.runtime.Composable
import androidx.compose.runtime.MutableState
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import dependencies.di
import managers.WebBrowserManager
import org.kodein.di.instance
import ui.screens.app.AppScreenEvent
import ui.screens.app.StartPagesRoute
import ui.screens.splash.splashSignInEmail.SplashSignInByEmailScreenEvent
import ui.screens.splash.splashSignUpAbout.SplashSignUpAboutEvent
import ui.screens.splash.splashStart.SplashScreenEvent
import web.screens.splash.JsSplashScreen
import web.screens.splash.JsSplashSignInScreen
import web.screens.splash.SplashSignUpNewScreen
import web.views.JsImagePreloaderQueue


@Composable
internal fun StartPagesNavigation(obtainEvent: (AppScreenEvent) -> Unit) {
    JsImagePreloaderQueue.addToQueue(
        listOf(
            "ic_logo.png",
            "ic_sign_up_nickname_web.webp",
            "ic_sign_up_birthday_web.webp",
            "ic_password.webp"
        )
    )

    val currentPage: MutableState<StartPagesRoute> =
        remember { mutableStateOf(StartPagesRoute.EnterScreen) }

    when (currentPage.value) {
        StartPagesRoute.EnterScreen -> {
            JsSplashScreen(
                obtainEvent = {
                    when (it) {
                        SplashScreenEvent.OnRegisterClick ->
                            currentPage.value = StartPagesRoute.RegisterScreen

                        SplashScreenEvent.OnLoginClick ->
                            currentPage.value = StartPagesRoute.LoginScreen

                        is SplashScreenEvent.SettingsWebPage -> {
                            val webBrowserManager by di.instance<WebBrowserManager>()
                            webBrowserManager.showWebPage(it.url)
                        }

                        SplashScreenEvent.ShowMainPage -> obtainEvent(AppScreenEvent.ShowMainPages)
                        SplashScreenEvent.ShowOnboardingStart -> obtainEvent(AppScreenEvent.ShowOnboardingPages)
                    }
                }
            )
        }

        StartPagesRoute.RegisterScreen -> {
            SplashSignUpNewScreen(
                obtainEvent = {
                    when (it) {
                        SplashSignUpAboutEvent.HideKeyboard -> {}
                        is SplashSignUpAboutEvent.ShowBirthdayPicker -> {}
                        SplashSignUpAboutEvent.OnBackClick ->
                            currentPage.value = StartPagesRoute.EnterScreen

                        SplashSignUpAboutEvent.OnBoardingStart ->
                            obtainEvent(AppScreenEvent.ShowOnboardingPages)

                        is SplashSignUpAboutEvent.SplashSignInEmail ->
                            currentPage.value = StartPagesRoute.LoginScreen
                    }
                }
            )
        }

        StartPagesRoute.LoginScreen -> {
            JsSplashSignInScreen(
                obtainEvent = {
                    when (it) {
                        SplashSignInByEmailScreenEvent.MainStart ->
                            obtainEvent(AppScreenEvent.ShowMainPages)

                        SplashSignInByEmailScreenEvent.OnBoardingStart ->
                            obtainEvent(AppScreenEvent.ShowOnboardingPages)

                        SplashSignInByEmailScreenEvent.SplashSignUp ->
                            currentPage.value = StartPagesRoute.RegisterScreen

                        SplashSignInByEmailScreenEvent.OnBackClick ->
                            currentPage.value = StartPagesRoute.EnterScreen
                    }
                }
            )
        }

        is StartPagesRoute.RegisterEmailScreen -> {}
        is StartPagesRoute.LoginEmailScreen -> {}
    }
}