class AccountRelationshipStatusConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountRelationshipStatus {
            var item = AccountRelationshipStatus.DO_NOT_SHOW
            enumValues<AccountRelationshipStatus>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}