@Composable
fun JsPaywallScreen(
    viewModelCallback: (PaywallScreenEvent) -> Unit,
    viewModel: PaywallScreenVM = rememberJsViewModel { PaywallScreenVM(viewModelCallback) }
) {
    val colorList = listOf(
        JsMainTheme.colors.gradient_subscribe_unlim_color_start,
        JsMainTheme.colors.gradient_subscribe_unlim_color_end
    )
    val finishDelay = remember { mutableStateOf(false) }
    val contentHeightPx = remember { mutableStateOf(0) }
    val lastScreenHeightPx = remember { mutableStateOf(0) }

    PageContainer {
        Box(Modifier.fillMaxSize()) {

            JsImageView(
                Res.drawable.bg_propose_subscription_new,
                Modifier.fillMaxWidth().heightIn(max = resultHeight.value.px),
                contentScale = ContentScale.FillWidth
            )

            JsImageView(
                Res.drawable.bg_propose_subscription_middle_level,
                format = "webp",
                modifier = Modifier.fillMaxWidth().height(resultHeight.value.px)
                    .zIndex(1).alpha(0.85f),
                contentScale = ContentScale.FillWidth
            )

            Column(
                Modifier.zIndex(2).fillMaxWidth().heightIn(min = resultHeight.value.px),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                PaywallTopImage(contentHeightPx)

                Column(
                    Modifier.fillMaxWidth().onSizeChanged { width, height ->
                        val screenHeight = resultHeight.value
                        if (lastScreenHeightPx.value != screenHeight.toInt()) {
                            viewModel.viewModelScope.launch {
                                delay(200)
                                lastScreenHeightPx.value = screenHeight.toInt()
                                contentHeightPx.value = height
                            }
                        }
                    },
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    PaywallTopTitle()
                    Spacer(Modifier.size(12.dp))
                    PaywallAllFeaturesContent(viewModel)
                    Spacer(Modifier.size(16.dp))

                    val usersAmount = if (AppVariant.isFiorry()) {
                        "1M+"
                    } else if (AppVariant.isHeaven()) {
                        "300k+"
                    } else {
                        "100k+"
                    }
                    val enjoyedByText = stringResource(
                        Res.string.onboarding_propose_subscription_enjoyed_by, usersAmount
                    )


                    JsSubscribeDiscountMain(
                        productDetails = viewModel.products,
                        enjoyedByText = enjoyedByText,
                        weekPrice = viewModel.weekPrice,
                        paywallButtonsStyle = 1,
                        showOtherProduct = {
                            viewModel.showingOtherSubscriptions.value = true
                        },
                        callback = { },
                        isReview = viewModel.isReview.value,
                        isWeekFormat = viewModel.products.firstOrNull { Billings.isWeekSubscribe(it.productDetails.productId) } != null,
                        annual12MonthsText = viewModel.annual12MonthsText.value,
                        cancelAnytimeNewStyle = viewModel.cancelAnytimeNewStyle.value
                    )

                    Box(modifier = Modifier.weight(1f).minHeight(12.dp))


                    JsButtonPulse(
                        buttonText = stringResource(Res.string.onboarding_finish_btn),
                        colors = colorList,
                        arrowIsVisible = true
                    ) {
                        //viewModel.showStripeAppleGoogle.value = true

                        val selectedProductId = viewModel.selectedProductID.value
                        val stripeProduct =
                            BillingManager.productDetailsList.firstOrNull { it.productId == selectedProductId }
                        viewModel.loadStripeClientSecret(stripeProduct)
                    }

                    JsSubscriptionTermsAndPrivacy(
                        isShowBottomTotalPrice = false,
                        billingManager = viewModel.billingManager,
                        selectedProductID = viewModel.selectedProductID,
                        annual12MonthsText = viewModel.annual12MonthsText.value,
                        onTermsClick = {
                            val webBrowserManager by di.instance<WebBrowserManager>()
                            webBrowserManager.showWebPage(Endpoint.getTermsUrl())
                        },
                        onPrivacyClick = {
                            val webBrowserManager by di.instance<WebBrowserManager>()
                            webBrowserManager.showWebPage(Endpoint.getPrivacyPolicyUrl())
                        }
                    )
                }
            }
        }

        Box(
            Modifier.size(48.dp).padding(start = 16.dp, top = 16.dp).zIndex(9)
                .clickable { viewModelCallback(PaywallScreenEvent.ShowMainPage()) },
        ) {
            JsImageView(Res.drawable.ic_delete_input, modifier = Modifier.size(24.dp))
        }

        OtherSection(viewModel, colorList)

        StripeByAppleGoogleScreen(
            viewModel,
            onPurchase = { paymentId, priceId, productId ->
                viewModel.setDefaultSelectedProduct()
                viewModel.showStripeAppleGoogle.value = false
                viewModel.buyStripeProduct(
                    paymentId = paymentId,
                    priceID = priceId,
                    productId = productId
                )
            }, onError = {
                //viewModel.setDefaultSelectedProduct()
                //viewModel.showStripeAppleGoogle.value = false
                viewModel.dialogManager.showMessageDialog(it)
            },
            onClose = {
                viewModel.setDefaultSelectedProduct()
                viewModel.showStripeAppleGoogle.value = false
            }
        )

        if (viewModel.waitingState.value) LoadingBlockState()

        if (contentHeightPx.value == 0 && !finishDelay.value) HideContentLoader()
        LaunchedEffect(Unit) {
            delay(500)
            finishDelay.value = true
        }
    }
}

@Composable
private fun PaywallTopImage(contentHeightPx: MutableState<Int>) {
    val imageHeightPx = remember { mutableStateOf(0) }
    val imageWidthPx = remember { mutableStateOf(0) }

    LaunchedEffect(resultHeight.value) {
        imageHeightPx.value = 0
    }

    val modifier = if (contentHeightPx.value > 0 && imageHeightPx.value > 0) {
        val imageHeight = resultWidth.value * (imageHeightPx.value / imageWidthPx.value.toDouble())
        val resultImageHeight: Int =
            if (resultHeight.value <= (contentHeightPx.value + imageHeight)) {
                val heightResult = ((resultHeight.value - contentHeightPx.value) - 10).toInt()
                if (heightResult > 0) heightResult else 0
            } else imageHeightPx.value
        Modifier.fillMaxWidth().height(resultImageHeight.px)
    } else Modifier.fillMaxSize().onSizeChanged { width, height ->
        imageWidthPx.value = width
        imageHeightPx.value = height
    }
    JsImageView(
        Res.drawable.ic_propose_subscription_logo_new,
        format = "webp",
        modifier = modifier,
        contentScale = ContentScale.FillWidth,
        align = Alignment.BottomCenter
    )
}

@Composable
private fun PaywallTopTitle() {
    val firstPart =
        stringResource(Res.string.onboarding_propose_subscription_new_text_first)
    val secondPart =
        stringResource(Res.string.onboarding_propose_subscription_new_text_second)
    val fullText = stringResource(
        Res.string.onboarding_propose_subscription_new_title, firstPart, secondPart
    )

    val firstPartStartIndex = fullText.indexOf(firstPart)
    val firstPartEndIndex = firstPartStartIndex + firstPart.length
    val secondPartStartIndex = fullText.indexOf(secondPart)
    val secondPartEndIndex = secondPartStartIndex + secondPart.length
    val bgColor = JsMainTheme.colors.subscribe_propose_fuchsia.copy(alpha = 0.4f)
    val customModifier = Modifier.background(bgColor).clipByCorner(4)

    val annotatedString = listOf(
        AnnotatedString(fullText.substring(0, firstPartStartIndex), null),
        AnnotatedString(fullText.substring(firstPartStartIndex, firstPartEndIndex), customModifier),
        AnnotatedString(fullText.substring(firstPartEndIndex, secondPartStartIndex), null),
        AnnotatedString(
            fullText.substring(secondPartStartIndex, secondPartEndIndex), customModifier
        ),
        AnnotatedString(fullText.substring(secondPartEndIndex, fullText.length), null)
    )

    JsAnnotatedStringsText(
        annotatedString,
        modifier = Modifier.fillMaxWidth(0.85f.toPercent()),
        textAlign = TextAlign.Center,
        textColor = JsMainTheme.colors.text_color_white,
        fontWeight = FontWeight.Bold,
        textSize = 22,
    )
}

@Composable
private fun PaywallAllFeaturesContent(viewModel: PaywallScreenVM) {
    val showingAllFeatures = viewModel.showingAllFeatures.value
    Row(
        Modifier.clickable {
            viewModel.showingAllFeatures.value = !viewModel.showingAllFeatures.value
        }.padding(horizontal = 16.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        val featuresText =
            if (showingAllFeatures) Res.string.subscribe_unlimited_settings_hide_text
            else Res.string.subscribe_unlimited_settings_show_text
        JsTextView(
            stringResource(featuresText), 15,
            textColor = JsMainTheme.colors.subscribe_propose_new_design_settings
        )

        val arrowIcon =
            if (showingAllFeatures) Res.drawable.ic_baseline_arrow_up_24
            else Res.drawable.ic_baseline_arrow_down_24
        JsImageView(
            arrowIcon,
            tintColor = JsMainTheme.colors.subscribe_propose_new_design_settings,
            modifier = Modifier.padding(top = 1.dp).size(12.dp),
            contentScale = ContentScale.FillWidth
        )
    }

    /*AnimatedVisibility(
        visible = showingAllFeatures,
        enter = fadeIn() + expandVertically(),
        exit = fadeOut() + shrinkVertically()
    ) {*/
    if (showingAllFeatures) Box(
        Modifier.fillMaxWidth().padding(top = 8.dp, start = 16.dp, end = 16.dp).clipByCorner(16)
    ) {
        Box(
            Modifier.fillMaxWidth()
                .overflow(Overflow.Hidden)
                .position(Position.Relative)
        ) {
            JsImageView(
                drawableRes = Res.drawable.bg_propose_subscribe_settings,
                format = "webp",
                modifier = Modifier.fillMaxSize().position(Position.Absolute)
                    .zIndex(0)
                    .clipByCorner(16),
                contentScale = ContentScale.FillBounds
            )

            Column(
                Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 12.dp).zIndex(1),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                JsPaywallSettingsFeatureText(Res.string.subscribe_unlimited_read_status_top_title)
                JsPaywallSettingsFeatureText(Res.string.subscribe_settings_unlimited_chats_and_profiles)
                JsPaywallSettingsFeatureText(Res.string.subscribe_settings_region)
                JsPaywallSettingsFeatureText(Res.string.subscribe_settings_online_status)
                JsPaywallSettingsFeatureText(Res.string.subscribe_settings_new_status)
                JsPaywallSettingsFeatureText(Res.string.subscribe_settings_incognito)
                JsPaywallSettingsFeatureText(Res.string.subscribe_settings_read_message)
                JsPaywallSettingsFeatureText(Res.string.subscribe_settings_profile_top)
                JsPaywallSettingsFeatureText(Res.string.subscribe_settings_location)
