enum class ChatMessageStatus(val resId: () -> String, val value: String) {
    SENDING(
        { "message_status_sending" }, "Sending..."
    ),
    SENT(
        { "message_status_sent" }, "Sent"
    ),
    DELIVERED(
        { "message_status_delivered" }, "Delivered"
    ),
    READ(
        { "message_status_read" }, "Read"
    ),
    FAILED(
        { "message_status_failed" }, "Failed to send"
    )

}