@Composable
fun JsAutoResizeText(
    text: String,
    maxTextSize: Int,
    minTextSize: Int = 0,
    modifier: Modifier = Modifier,
    fontWeight: FontWeight = FontWeight.Normal,
    color: Color = JsMainTheme.colors.text_color_default,
    textAlign: TextAlign = TextAlign.Start,
    overflow: TextOverflow = TextOverflow.Clip,
    textDecoration: TextDecorationLine = TextDecorationLine.None,
    maxLines: Int? = null,
) {
    val elementRef = remember { mutableStateOf<HTMLElement?>(null) }
    var fontSize by remember { mutableStateOf(maxTextSize) }

    LaunchedEffect(text, maxTextSize, minTextSize, elementRef.value) {
        val el = elementRef.value ?: return@LaunchedEffect
        var currentSize = maxTextSize
        el.style.fontSize = "${currentSize}px"

        while (
            (el.scrollWidth > el.clientWidth || el.scrollHeight > el.clientHeight) &&
            currentSize > minTextSize
        ) {
            currentSize--
            el.style.fontSize = "${currentSize}px"
        }
        fontSize = currentSize
    }

    Span(
        attrs = modifier
            .textDecorationLine(textDecoration)
            .styleModifier {
                fontSize(getMaxMinSize(fontSize).max.cssRem)
                color(color)
                fontWeight(fontWeight)
                userSelect(UserSelect.None)
                if (maxLines != null) {
                    display(DisplayStyle("-webkit-box"))
                    property("-webkit-line-clamp", maxLines.toString())
                    property("-webkit-box-orient", "vertical")
                    textOverflow(overflow)
                }
                overflow(Overflow.Hidden)
                whiteSpace("pre-wrap")
                textAlign(textAlign)
            }
            .toAttrs {
                ref {
                    elementRef.value = it
                    onDispose {  }
                }
            }
    ) {
        Text(text)
    }
}


@Composable
fun JsTextView(
    text: String,
    textSize: Int,
    modifier: Modifier = Modifier,
    fontWeight: FontWeight = FontWeight.Normal,
    textColor: Color = JsMainTheme.colors.text_color_default,
    textAlign: TextAlign = TextAlign.Start,
    textDecoration: TextDecorationLine = TextDecorationLine.None,
    maxLines: Int? = null,
    userSelect: UserSelect = UserSelect.None,
) {
    val maxMin = getMaxMinSize(textSize)

    Span(
        attrs = modifier.textDecorationLine(textDecoration)
            .styleModifier {
                fontSize(maxMin.max.cssRem)
                color(textColor)
                fontWeight(fontWeight)
                userSelect(userSelect)
                if (maxLines != null) {
                    display(DisplayStyle("-webkit-box"))
                    property("-webkit-line-clamp", maxLines.toString())
                    property("-webkit-box-orient", "vertical")
                    textOverflow(TextOverflow.Ellipsis)
                }
                whiteSpace("pre-wrap")
                overflow(Overflow.Hidden)
                textAlign(textAlign)
            }.toAttrs()
    ) {
        Text(text)
    }
}

data class AnnotatedString(val text: String, val modifier: Modifier?, val textSize: Int? = null)
data class TextMaxMinSize(val max: Double, val min: Double)


@Composable
fun JsAnnotatedStringsText(
    annotatedStrings: List<AnnotatedString>,
    textSize: Int,
    fontWeight: FontWeight = FontWeight.Normal,
    textColor: Color = JsMainTheme.colors.text_color_default,
    modifier: Modifier = Modifier,
    textAlign: TextAlign = TextAlign.Start,
    overflow: TextOverflow = TextOverflow.Clip,
    maxLines: Int? = null,
    userSelect: UserSelect = UserSelect.None,
) {
    val maxMin = getMaxMinSize(textSize)
    Span(
        attrs = modifier.styleModifier {
            fontSize(maxMin.max.cssRem)
            color(textColor)
            fontWeight(fontWeight)
            userSelect(userSelect)
            if (maxLines != null) {
                display(DisplayStyle("-webkit-box"))
                property("-webkit-line-clamp", maxLines.toString())
                property("-webkit-box-orient", "vertical")
                textOverflow(overflow)
            }
            whiteSpace("pre-wrap")
            overflow(Overflow.Hidden)
            textAlign(textAlign)
        }.toAttrs()
    ) {
        annotatedStrings.forEach {
            var customModifier = it.modifier
            if (customModifier == null) Text(it.text)
            else {
                customModifier = customModifier.styleModifier {
                    val customTextSize = it.textSize
                    if (customTextSize != null) {
                        val customSize = getMaxMinSize(customTextSize)
                        fontSize(customSize.max.cssRem)
                    } else fontSize(maxMin.max.cssRem)
                }
                Span(attrs = customModifier.toAttrs()) { Text(it.text) }
            }
        }
    }
}

@Composable
fun JsOutlinedTextField(
    value: String,
    textSize: Int,
    textColor: Color = Colors.White,
    modifier: Modifier = Modifier.fillMaxWidth(),
    textMinHeight: Int? = null,
    label: String? = null,
    labelColor: Color = JsMainTheme.colors.text_color_hint,
    placeholder: String? = null,
    backgroundColor: Color = Color.rgb(0X282B30),
    isEnabled: Boolean = true,
    readOnly: Boolean = false,
    isError: Boolean = false,
    errorText: String? = null,
    errorColor: Color = JsMainTheme.colors.main_color_error,
    singleLine: Boolean = true,
    rightIcon: String? = null,
    rightIconClick: (() -> Unit)? = null,
    inputType: InputType<String> = InputType.Text,
    onValueChange: (String) -> Unit = {},
    onNext: () -> Unit = {},
    onClick: (() -> Unit)? = null,
) {
    var isFocused by remember { mutableStateOf(false) }

    var textModifier = Modifier.styleModifier {
        border(0.dp)
        outline("none")
    }
    if (textMinHeight != null) textModifier = textModifier.minHeight(50.dp)


    Column(modifier = modifier) {
        if (!label.isNullOrEmpty()) {
            JsTextView(
                label,
                textSize = textSize,
                textColor = labelColor,
                modifier = Modifier.padding(bottom = 4.dp, left = 24.dp)
            )
        }

        var containerModifier = Modifier.fillMaxWidth()
            .padding(left = 24.dp, right = 24.dp)
            .background(backgroundColor)
            .clipByCorner(9999)

        containerModifier = if (isError) containerModifier.border(
            1.dp,
            LineStyle.Solid,
            JsMainTheme.colors.main_color_error
        )
        else if (isFocused) containerModifier.border(
            1.dp,
            LineStyle.Solid,
            JsMainTheme.colors.app_main_color
        )
        else containerModifier.border(1.dp, LineStyle.Solid, backgroundColor)

        if (onClick != null) containerModifier = containerModifier.clickable { onClick() }

        Row(
            modifier = containerModifier, verticalAlignment = Alignment.CenterVertically
        ) {
            Input(
                type = inputType,
                value = value,
                modifier = textModifier.weight(1f)
                    .color(textColor)
                    .onFocusIn { isFocused = true }
                    .onFocusOut { isFocused = false }
                    .onKeyDown {
                        if (it.key == "Enter") {
                            moveOrClearFocus()
                            onNext()
                        }
                    },
                readOnly = readOnly,
                enabled = isEnabled,
                onValueChange = onValueChange,
                placeholder = placeholder,
                focusBorderColor = Colors.Transparent,
                invalidBorderColor = errorColor
            )

            if (!rightIcon.isNullOrEmpty()) {
                JsImageView(rightIcon, Modifier.size(22.dp).clickable {
                    rightIconClick?.invoke()
                })
            }
        }

        JsTextView(
            text = if (isError) errorText ?: "" else "",
            textSize = textSize - 2,
            textColor = errorColor,
            modifier = Modifier.padding(left = 24.dp, bottom = 4.dp)
        )
    }
}

fun getMaxMinSize(textSize: Int, minTextSize: Int? = null): TextMaxMinSize {
    val remSize = textSize / 16.0 // 1 rem = 16px
    val minSize = (minTextSize ?: textSize) / 16.0

    val minAbsolute = if (isMobileDevice) {
        if (AppVariant.isIos()) 0.9 else 0.8
    } else 0.75

    val minRemSize = if (isMobileDevice) {
        if (AppVariant.isIos()) minSize * 0.9 else minSize * 0.8
    } else minSize * 0.7

    val min = maxOf(minAbsolute, minRemSize)
    val max = if (isMobileDevice) {
        if (AppVariant.isIos()) remSize * 1.15 else remSize * 1.05
    } else remSize * 1.0
    return TextMaxMinSize(max, min)
}

private fun moveOrClearFocus() {
    val activeElement = document.activeElement as? HTMLElement
    if (activeElement != null) {
        val inputs = document.querySelectorAll("input")
        val currentIndex = inputs.indexOf(activeElement)
        if (currentIndex != -1 && currentIndex < inputs.length - 1) {
            (inputs[currentIndex + 1] as? HTMLElement)?.focus()
        } else {
            activeElement.blur()
        }
    }
}

private fun <T> org.w3c.dom.NodeList.indexOf(node: T): Int {
    for (i in 0 until this.length) {
        if (this[i] == node) return i
    }
    return -1
}
