data class CropRect(val left: Double, val top: Double, val width: Double, val height: Double) {
    val right get() = left + width
    val bottom get() = top + height
}

@Composable
fun ImageCropJs(
    imageUrl: String,
    zoom: Float, // Внешний стейт зума (например, от Slider)
    onZoomChange: (Float) -> Unit, // Коллбек для изменения зума
    onCropRectChanged: (CropRect) -> Unit
) {
    var containerWidth by remember { mutableStateOf(0.0) }
    var containerHeight by remember { mutableStateOf(0.0) }

    var imageNaturalWidth by remember { mutableStateOf(0.0) }
    var imageNaturalHeight by remember { mutableStateOf(0.0) }

    var offsetX by remember { mutableStateOf(0.0) }
    var offsetY by remember { mutableStateOf(0.0) }

    var isDragging by remember { mutableStateOf(false) }
    var lastDragX by remember { mutableStateOf(0.0) }
    var lastDragY by remember { mutableStateOf(0.0) }

    // 1. Расчет рамки
    val cropRect = remember(containerWidth, containerHeight) {
        if (containerWidth == 0.0 || containerHeight == 0.0) return@remember null

        val margin = 0.0
        val availableWidth = containerWidth - margin * 2
        val availableHeight = containerHeight - margin * 2

        var targetWidth = availableWidth
        var targetHeight = targetWidth * 1.2

        if (targetHeight > availableHeight) {
            targetHeight = availableHeight
            targetWidth = targetHeight / 1.2
        }

        val left = (containerWidth - targetWidth) / 2
        val top = (containerHeight - targetHeight) / 2

        CropRect(left, top, targetWidth, targetHeight)
    }

    LaunchedEffect(cropRect) {
        if (cropRect != null) onCropRectChanged(cropRect)
    }

    // 2. Ограничения (Clamping)
    fun clampOffset(proposedX: Double, proposedY: Double, currentZoom: Float): Pair<Double, Double> {
        if (cropRect == null || imageNaturalWidth == 0.0) return 0.0 to 0.0

        val screenRatio = containerWidth / containerHeight
        val imgRatio = imageNaturalWidth / imageNaturalHeight

        val renderedWidth = if (imgRatio > screenRatio) containerWidth else containerHeight * imgRatio
        val renderedHeight = if (imgRatio > screenRatio) containerWidth / imgRatio else containerHeight

        val currentWidth = renderedWidth * currentZoom
        val currentHeight = renderedHeight * currentZoom

        val maxOffsetX = max(0.0, (currentWidth - cropRect.width) / 2)
        val maxOffsetY = max(0.0, (currentHeight - cropRect.height) / 2)

        val finalX = proposedX.coerceIn(-maxOffsetX, maxOffsetX)
        val finalY = proposedY.coerceIn(-maxOffsetY, maxOffsetY)

        return finalX to finalY
    }

    // При изменении входящего zoom пересчитываем смещение, чтобы картинка не улетела
    LaunchedEffect(zoom) {
        val (clampedX, clampedY) = clampOffset(offsetX, offsetY, zoom)
        if (clampedX != offsetX || clampedY != offsetY) {
            offsetX = clampedX
            offsetY = clampedY
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .overflow(Overflow.Hidden)
            .cursor(if (isDragging) Cursor.Grabbing else Cursor.Grab)
            .userSelect(UserSelect.None)
            // Жесты мыши
            .onMouseDown { evt ->
                isDragging = true
                lastDragX = evt.clientX.toDouble()
                lastDragY = evt.clientY.toDouble()
            }
            .onMouseMove { evt ->
                if (isDragging) {
                    val dx = evt.clientX.toDouble() - lastDragX
                    val dy = evt.clientY.toDouble() - lastDragY
                    lastDragX = evt.clientX.toDouble()
                    lastDragY = evt.clientY.toDouble()

                    val (newX, newY) = clampOffset(offsetX + dx, offsetY + dy, zoom)
                    offsetX = newX
                    offsetY = newY
                }
            }
            .onMouseUp { isDragging = false }
            .onMouseLeave { isDragging = false }
            // Зум колесиком -> вызываем onZoomChange
            .onWheel { evt ->
                evt.preventDefault()
                val delta = -evt.clientY.coerceIn(-100, 100) * 0.001
                // Вычисляем новый зум и передаем наверх
                val newZoom = (zoom + delta.toFloat() * zoom).coerceIn(1f, 10f)
                onZoomChange(newZoom)
            },
        // Используем ref для ResizeObserver
        ref = ref { element ->
            val observer = ResizeObserver { entries, _ ->
                entries.firstOrNull()?.contentRect?.let {
                    containerWidth = it.width
                    containerHeight = it.height
                }
            }
            observer.observe(element)

            // Вместо onDispose { ... } возвращаем объект DisposableEffectResult
            object : DisposableEffectResult {
                override fun dispose() {
                    observer.disconnect()
                }
            }
        }
    ) {
        // Изображение
        Img(
            src = imageUrl,
            attrs = {
                style {
                    width(100.percent)
                    height(100.percent)
                    property("object-fit", "contain")
                    property("transform", "translate(${offsetX}px, ${offsetY}px) scale($zoom)")
                    property("transition", if (isDragging) "none" else "transform 0.1s ease-out")
                    property("user-select", "none")
                    property("-webkit-user-drag", "none")
                }
                ref { element ->
                        if (element.complete && element.naturalWidth > 0) {
                            imageNaturalWidth = element.naturalWidth.toDouble()
                            imageNaturalHeight = element.naturalHeight.toDouble()
                        }
                        element.onload = {
                            imageNaturalWidth = element.naturalWidth.toDouble()
                            imageNaturalHeight = element.naturalHeight.toDouble()
                            Unit
                        }
                    // Пустой dispose, так как мы ничего не подписывали
                    object : DisposableEffectResult {
                        override fun dispose() {}
                    }
                }
            }
        )

        // Overlay
        if (cropRect != null) {

            val tint = JsMainTheme.colors.main_color_black_transparent_30
            val borderColor = JsMainTheme.colors.app_main_color

            // Верх
            Box(Modifier
                .position(Position.Absolute)
                .top(0.px).left(0.px)
                .width(100.percent).height(cropRect.top.px)
                .backgroundColor(tint)
            )
            // Низ
            Box(Modifier
                .position(Position.Absolute)
                .top(cropRect.bottom.px).left(0.px)
                .width(100.percent).height((containerHeight - cropRect.bottom).px)
                .backgroundColor(tint)
            )
            // Лево
            Box(Modifier
                .position(Position.Absolute)
                .top(cropRect.top.px).left(0.px)
                .width(cropRect.left.px).height(cropRect.height.px)
                .backgroundColor(tint)
            )
            // Право
            Box(Modifier
                .position(Position.Absolute)
                .top(cropRect.top.px).left(cropRect.right.px)
                .width((containerWidth - cropRect.right).px).height(cropRect.height.px)
                .backgroundColor(tint)
            )

            // Рамка
            Box(Modifier
                .position(Position.Absolute)
                .top(cropRect.top.px).left(cropRect.left.px)
                .width(cropRect.width.px).height(cropRect.height.px)
                .styleModifier {
                    property("border", "2px solid white")
                    property("pointer-events", "none")
                }
            )
        }
    }
}

// Вспомогательные классы для JS API
external class ResizeObserver(callback: (Array<ResizeObserverEntry>, ResizeObserver) -> Unit) {
    fun observe(target: org.w3c.dom.Element)
    fun disconnect()
}
external interface ResizeObserverEntry {
    val contentRect: DOMRectReadOnly
}
external interface DOMRectReadOnly {
    val width: Double
    val height: Double
}