@Composable
fun ProfilePhotoCropScreenJs(
    image: String,
    onBack: () -> Unit,
    cropPhoto: (String) -> Unit
) {

    val rotation = remember { mutableStateOf(0.0) } // 0, 90, 180, 270
    val zoomLevel = remember { mutableStateOf(1f) }
    PageColumnContainer {
        JsCropImageTabBar(
            rotate = { rotation.value = (rotation.value + 90) % 360 },
            onBack = onBack
        )

        Box(
            Modifier.fillMaxWidth()
                .weight(1)
                .alignItems(AlignItems.Center)
                .justifyContent(JustifyContent.Center)
        ) {
            ImageCropJs(
                imageUrl = image,
                zoom = zoomLevel.value,
                onZoomChange = { zoomLevel.value = it},
                onCropRectChanged = {}
            )

            ZoomControlPanelJs(
                modifier = Modifier.align(Alignment.BottomCenter),
                zoomLevel = zoomLevel.value,
                onZoomChange = {
                    zoomLevel.value = it
                }
            )
        }

        val colors = listOf(
            JsMainTheme.colors.gradient_subscribe_unlim_color_start,
            JsMainTheme.colors.gradient_subscribe_unlim_color_end
        )
        JsMainButtonCustom(
            text = stringResource(Res.string.people_profile_download_photo_title),
            colors = colors
        ) { cropPhoto.invoke("") }
    }
}

@Composable
