enum class SplashSignInByEmailScreenEvent {
    MainStart,
    OnBoardingStart,
    SplashSignUp,
    OnBackClick
}

class SplashSignInByEmailVM(
    val phoneCode: String,
    val phoneNumber: String,
    val authorizationType: AuthorizationType,
    val obtainEvent: (SplashSignInByEmailScreenEvent) -> Unit
) : ViewModel() {

    private val firebaseManager by di.instance<IFirebaseManager>()
    private val dialogManager by di.instance<IDialogManager>()
    private val repositoriesProvider by di.instance<RepositoriesProvider>()
    private val accountRepository = repositoriesProvider.accountRepository
    private val chatRepository = repositoriesProvider.chatRepository

    val phoneNumberValue = mutableStateOf("")
    val phoneNumberErrorValue = mutableStateOf("")
    val phoneCodeValue = mutableStateOf("")

    val emailValue = mutableStateOf(TextFieldValue(""))
    val emailErrorValue = mutableStateOf("")

    val passwordValue = mutableStateOf("")
    val passwordErrorValue = mutableStateOf("")
    val emailType = authorizationType == AuthorizationType.EMAIL

    val showProgress = mutableStateOf(false)

    init {
        phoneCodeValue.value = phoneCode

        if (AppVariant.isLocalSettings()) {
            emailValue.value = TextFieldValue("shch.avinskiyb@gmail.com")
            passwordValue.value = "12345678"
        }
    }

    private fun showMainPage(account: Account?) {
        showProgress.value = false

        fun isNotEmptyAccount() {
            repositoriesProvider.setStartValues()
            firebaseManager.init()
            chatRepository.connectWebSocket("4.4.4")
            obtainEvent(SplashSignInByEmailScreenEvent.MainStart)
        }

        if (account?.info?.iamList.isNullOrEmpty() || account?.info?.interestedIn.isNullOrEmpty()) {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val myAccount = accountRepository.getMyAccount()
                if (myAccount?.info?.iamList.isNullOrEmpty() || myAccount?.info?.interestedIn.isNullOrEmpty())
                    obtainEvent(SplashSignInByEmailScreenEvent.OnBoardingStart)
                else isNotEmptyAccount()
            }
        } else isNotEmptyAccount()
    }

    fun continueSignUp() {
        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInToRegistrationClick.name)
        obtainEvent(SplashSignInByEmailScreenEvent.SplashSignUp)
    }

    private var lastClickTime = 0L

    fun continueSignIn(isDuplicate: Boolean = false) {
        val currentTime = Date.currentTimeMillis()
        if (currentTime - lastClickTime < 1500) return
        lastClickTime = currentTime
        val password = passwordValue.value

        val login = if (!emailType) {
            "${phoneCodeValue.value}${phoneNumberValue.value}".trim()
        } else emailValue.value.text.trim()

        var haveError = false
        if (emailType && !EmailValid.isEmailValid(login)) {
            emailError()
            haveError = true
        }
        if (!emailType && (login.length < 6 || login.length > 20)) {
            showError("")
            haveError = true
        }
        if (password.length < 6) {
            showError(Res.string.error_message_sign_password_at_least)
            haveError = true
        }
        if (haveError) return

//        if (AppVariant.isDebug()) {
//            obtainEvent(SplashSignInByEmailScreenEvent.OnBoardingStart)
//            return
//        }
        showProgress.value = true

        if (!emailType) {
            if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInPhoneTopButton.name)
            else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInPhoneBottomButton.name)

            accountRepository.loginByPhone(login, password, {
                AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInSuccessMobile.name)
                showMainPage(it)
            }, onError = { showError(it) })
        } else {
            if (isDuplicate) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInEmailTopButton.name)
            else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInEmailBottomButton.name)

            val amplitudeManager by di.instance<AmplitudeManager>()
            accountRepository.loginByEmail(login, password, {
                AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInSuccessEmail.name)
                amplitudeManager.sendEvent(AmplitudeEvent.OnboardingSignInScreenShown(false))

                it?.info?.iamList?.first()?.let { myGender ->
                    val iamGender = AccountIam.entries.first { it.position == myGender }
                    val gender = AmplitudeAccountGender.getGenderByAccountIAmPosition(iamGender)
                    amplitudeManager.sendIdentify("gender", gender.name)
                }
                val subscriptionActive =
                    if ((it?.subscriptionStatus?.subscription?.type ?: 0) > 0) "yes" else "no"
                amplitudeManager.sendIdentify("subscription_active", subscriptionActive)
                showMainPage(it)
            }, onError = {
                showError(it)
                amplitudeManager.sendEvent(AmplitudeEvent.OnboardingSignInScreenShown(true))
            })
        }
    }


    fun checkEmailError(emailErrorText: String): Boolean {
        val email = emailValue.value.text.trim()
        val isEmailValid = EmailValid.isEmailValid(email)
        if ((email.isEmpty() && emailType) || (email.isNotEmpty() && !isEmailValid)) {
            emailErrorValue.value = emailErrorText
            return true
        }
        return false
    }

    fun checkPasswordError(passwordErrorText: String): Boolean {
        val password = passwordValue.value
        if ((password.isEmpty() || password.length < 6)) {
            passwordErrorValue.value = passwordErrorText
            return true
        }
        return false
    }

    private fun emailError() {
        viewModelScope.launch(Dispatchers.Main) {
            val invalidEmail = ResManager.getString(Res.string.error_message_sign_in_invalid_email)
            showError(invalidEmail)
        }
    }

    private fun showError(errorMessage: String?) {
        showProgress.value = false
        showError(null, errorMessage)
    }

    private fun showError(error: StringResource?, errorMessage: String? = null) {
        viewModelScope.launch(Dispatchers.Main) {
            val accountNotFoundError =
                ResManager.getString(Res.string.error_message_sign_in_account)
            val accountPasswordError =
                ResManager.getString(Res.string.error_message_sign_password_at_least)
            val accountNumberError =
                ResManager.getString(Res.string.error_message_sign_in_invalid_number)
            val accountEmailError =
                ResManager.getString(Res.string.error_message_sign_in_invalid_email)
            val authTokenError =
                ResManager.getString(Res.string.error_message_sign_in_auth_token)
            val authIdError =
                ResManager.getString(Res.string.error_message_sign_in_auth_id)
            val notValidError =
                ResManager.getString(Res.string.error_message_password_not_valid)
            val invalidPasswordError =
                ResManager.getString(Res.string.error_message_sign_in_invalid_password)

            val errorText = errorMessage ?: error?.let { ResManager.getString(it) }
            val accountError = errorText?.contains(accountNotFoundError) == true
                    || errorText?.contains(accountNumberError) == true
                    || errorText?.contains(accountEmailError) == true
                    || errorText?.contains(authIdError) == true
            if (errorText?.contains(accountNotFoundError) == true) {
                showRegistrationDialog()
            }

            val passwordError =
                errorText?.contains(notValidError) ?: false
                        || errorText?.contains(invalidPasswordError) ?: false
                        || errorText?.contains(authTokenError) ?: false
                        || errorText?.contains(accountPasswordError) ?: false
            if (passwordError) {
                passwordErrorValue.value =
                    if (errorText?.contains(accountPasswordError) == true)
                        ResManager.getString(Res.string.auth_sign_in_wrong_password_min_size)
                    else ResManager.getString(Res.string.auth_sign_in_wrong_password)
            }

            if (accountError) {
                if (!emailType) {
                    phoneNumberErrorValue.value =
                        ResManager.getString(Res.string.auth_sign_in_incorrect_number)
                } else {
                    emailErrorValue.value =
                        ResManager.getString(Res.string.auth_sign_in_incorrect_email)
                }
            }

            if (!accountError && !passwordError && !errorText.isNullOrEmpty())
                dialogManager.showDialog(ShowAlertState.ShowDefaultDialog(errorText, null))
        }
    }

    private fun showRegistrationDialog() {
        //val text = if (!emailType) phonePicker.number else binding.signInEmail.text.toString()
        viewModelScope.launch(Dispatchers.Main) {
            val title = ResManager.getString(Res.string.error_message_warning_title)
            val text = ResManager.getString(Res.string.dialog_splash_sign_in_register_text)
            val okBtn = ResManager.getString(Res.string.dialog_btn_sign_in)
            val cancelBtn = ResManager.getString(Res.string.btn_cancel)

            dialogManager.showDialog(
                ShowAlertState.ShowOkCancelDialog(
                    title, text, okBtn, cancelBtn, onOkClick = {
                        obtainEvent(SplashSignInByEmailScreenEvent.SplashSignUp)
                    })
            )
        }
    }

    fun remindPassword() {
        fun forgotPass() {
            if (emailType) AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInForgotPasswordEmail.name)
            else AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInForgotPasswordPhoneNumber.name)
            showPhoneDialog()
        }
        /*accountRepository.checkBanDevice {*/ forgotPass() //}
    }

    val showResetPasswordDialog = mutableStateOf(false)
    var login = ""
    private fun showPhoneDialog() {
        showResetPasswordDialog.value = true
//        if (emailType) router.route(Destination.DialogResetPassword(authorizationType, login))
//        else router.route(Destination.DialogResetPassword(authorizationType, login))
    }

    fun banDevice() {
        accountRepository.banDevice()
    }

}