@Composable
fun MenuPhotosBottomSheetJs(
    modifier: Modifier,
    onMenuCameraClick: () -> Unit,
    onMenuPhotosClick: () -> Unit,
) {

    Box(
        modifier = modifier.fillMaxWidth().background(JsMainTheme.colors.main_color_header),
        contentAlignment = Alignment.Center
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(75.percent).margin(top = 14.dp, bottom = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center
        ) {
            val itemModifier = Modifier.weight(1f).aspectRatio(1.2f / 0.8f)
                .margin(leftRight = 6.dp).background(JsMainTheme.colors.main_color_pick_photo_items_bg).clipByCorner(6)

            ItemMenuPhotosBottomSheetJs(
                modifier = itemModifier,
                image = "ic_take_photo_web",
                title = Res.string.onboarding_select_photos_take,
                onClick = onMenuCameraClick
            )

            ItemMenuPhotosBottomSheetJs(
                modifier = itemModifier,
                image = "ic_library_web",
                title = Res.string.onboarding_select_photos_pick,
                onClick = onMenuPhotosClick
            )
        }
    }
}

@Composable
fun ItemMenuPhotosBottomSheetJs(
    modifier: Modifier,
    image: String,
    format: String = "png",
    title: StringResource,
    onClick: () -> Unit,
) {
    Box(
        modifier = modifier.clickable { onClick.invoke() },
        contentAlignment = Alignment.Center
    ) {
        Column(
            verticalArrangement = Arrangement.Center,
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            JsImageViewTint(
                drawableId = image,
                tintColor = JsMainTheme.colors.app_main_color,
                format = format,
                contentScale = ContentScale.FillWidth,
                modifier = Modifier.margin(16.px).size(48.px)
            )
            Box(modifier = Modifier.height(8.dp))
            JsTextView(
                text = web.helpers.stringResource(resource = title),
                textSize = 12,
                textAlign = com.varabyte.kobweb.compose.css.TextAlign.Center
            )
        }
    }
}