import network.restApi.requests.ChatRequests
import org.kodein.di.instance

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 28.05.2021.
 */
class SocketRequestsResponseManager(
    val appKeys: IAppKeysStorage,
    private val notificationsUtils: INotificationManager,
    val readMessages: (Int, MutableList<String>) -> Unit
) {

    var currentOpenChatUserId: String? = null
    var currentOpenChatId: String? = null
    var accountCallback: (result: Any) -> Unit = {}
    var successCallbacks = hashMapOf<String, (String?) -> Unit>()
    var errorCallbacks = hashMapOf<String, (String?) -> Unit>()

    private fun socketObjectResponse(result: SocketReceived, local: Boolean = true) {
        val successCallback = successCallbacks[result.event] ?: {}
        when (result.event) {
            SocketEvent.BlockAccount.getResponse() -> {
                successCallback(null)
                EventBusManager.post(UpdateChatsCounter())
            }
            SocketEvent.CreateRequest.getResponse(), SocketEvent.GetChat.getResponse(),
            SocketEvent.Gift.getResponse() -> successCallback(result.data)
            SocketEvent.Session.getResponse() -> appKeys.sessionSend = true
            SocketEvent.BlockAccount.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<AccountBlockUser>(it) }
                EventBusManager.post(BlockAccount(data?.accountId ?: 0))
                EventBusManager.post(UpdateChatsCounter())
            }
            SocketEvent.BanAccount.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<AccountBlockUser>(it) }
                        ?: return
                EventBusManager.post(BanAccount(data.accountId))
            }
            SocketEvent.BanAccountPermanent.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<AccountBlockUser>(it) }
                        ?: return
                EventBusManager.post(BanAccountPermanent(data.accountId))
            }
            SocketEvent.DeleteChat.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<MessageResult>(it) }
                        ?: return
                EventBusManager.post(DeleteChat(data.chatId ?: 0))
            }
            SocketEvent.StartDeleteMessageTimer.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<MessageResult>(it) }
                if (data == null) successCallback(null)
                else EventBusManager.post(UpdateChatMessage(data))
            }
            SocketEvent.DeleteMessage.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<MessageResult>(it) }
                        ?: return
                EventBusManager.post(DeleteChatMessage(data))
                EventBusManager.post(UpdateChatsCounter())
            }
            SocketEvent.CreatingMessage.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<SocketStartMessage>(it) }
                        ?: return
                EventBusManager.post(UserTyping(data))
            }
            SocketEvent.Wow.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<WowResult>(it) }
                        ?: return
                notificationsUtils.showWowNotification(data, local)
                ChatRequests.wowUnreadMessages = true
                EventBusManager.post(NewWow(data))
            }
            SocketEvent.Message.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<MessageResult>(it) }
                        ?: return

                val currentChat = currentOpenChatUserId == data.senderId.toString()
                ChatRequests.chatUnreadMessages = true
                if (currentOpenChatUserId != null && currentChat) {
                    EventBusManager.post(NewMessageCurrentChat(data))
                    data.chatId?.let { readMessages(it, mutableListOf(data.uuid ?: "")) }
                    if (!ChatRequests.chatOpen)
                        notificationsUtils.showMessageNotification(data, local)
                } else {
                    EventBusManager.post(NewMessage(data))
                    notificationsUtils.showMessageNotification(data, local)
                }
            }
            SocketEvent.Gift.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<MessageResult>(it) }
                        ?: return

                val currentChat = currentOpenChatUserId == data.senderId.toString()
                ChatRequests.chatUnreadMessages = true
                if (currentOpenChatUserId != null && currentChat) {
                    EventBusManager.post(NewMessageCurrentChat(data))
                    data.chatId?.let { readMessages(it, mutableListOf(data.uuid ?: "")) }
                    if (!ChatRequests.chatOpen)
                        notificationsUtils.showMessageNotification(data, local, isGift = true)
                } else {
                    EventBusManager.post(NewMessage(data))
                    notificationsUtils.showMessageNotification(data, local, isGift = true)
                }
            }
            SocketEvent.CreateRequest.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<MessageResult>(it) }
                        ?: return

                val currentChat = currentOpenChatUserId == data.senderId.toString()
                ChatRequests.chatUnreadMessages = true
                if (currentOpenChatUserId != null && currentChat) {
                    EventBusManager.post(NewMessageCurrentRequest(data))
                    data.chatId?.let { readMessages(it, mutableListOf(data.uuid ?: "")) }
                    if (!ChatRequests.chatOpen) notificationsUtils.showMessageNotification(
                        data, local, true
                    )
                } else {
                    EventBusManager.post(NewMessage(data))
                    notificationsUtils.showMessageNotification(data, local, true)
                }
            }
            SocketEvent.ReadMessages.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<SocketRead>(it) }
                        ?: return

                val currentChat = currentOpenChatId == data.chatId.toString()
                ChatRequests.chatUnreadMessages = false
                val messageIds = data.messages
                if (currentOpenChatUserId != null && currentChat && messageIds != null) {
                    EventBusManager.post(ReadMessagesInterlocutor(messageIds))
                }
            }
            SocketEvent.News.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<NewsResult>(it) }
                        ?: return
                EventBusManager.post(ShowNewsEvent(data))
            }
            SocketEvent.TryTrial.event -> {
                val data =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<TryTrialResult>(it) }
                        ?: return
                if (data.productId.isEmpty()) return
                EventBusManager.post(ShowTryTrialEvent(data.productId))
            }
            SocketEvent.AccountConnected.event -> {
                val userId =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<Int>(it) } ?: return
                accountCallback(UserChangeStatus(userId, true))
            }
            SocketEvent.AccountDisconnected.event -> {
                val userId =
                    result.data?.let { JsonObjectConverter.jsonObjectToObject<Int>(it) } ?: return
                accountCallback(UserChangeStatus(userId, false))
            }
            else -> successCallback(null)
        }
        removeCallback(result.event)
    }

    private fun socketNullResponse(event: String) {
        val successCallback = successCallbacks[event] ?: {}
        when (event) {
            SocketEvent.GetChat.getResponse() -> successCallback(null)
            SocketEvent.BanAccount.event -> EventBusManager.post(BanAccount())
            SocketEvent.BanAccountPermanent.event -> EventBusManager.post(BanAccountPermanent())
            else -> {
            }
        }
        removeCallback(event)
    }

    fun socketResponse(json: String, local: Boolean = true) {
        val haveError = checkError(json)
        if (haveError) return

        val socketReceived = try {
            val receivedObject = JsonObjectConverter.stringToObject<SocketReceivedObject>(json)
            convertSocketReceivedObject(receivedObject)
        } catch (e: Throwable) {
            val receivedPrimitive = JsonObjectConverter.stringToObject<SocketReceivedPrimitive>(json)
            convertSocketReceivedPrimitive(receivedPrimitive)
        }
        if (socketReceived?.data != null) {
            socketObjectResponse(socketReceived, local)
        } else {
            val result = JsonObjectConverter.stringToObject<SocketReceived>(json) ?: return
            socketNullResponse(result.event)
        }
    }

    private fun checkError(json: String): Boolean {
        val result = JsonObjectConverter.stringToObject<SocketReceivedError>(json) ?: return false
        val errorCallback = errorCallbacks[result.event] ?: {}
        if (result.status == "error") {
            if (result.event == SocketEvent.AccountSessionExpired.event) {
                WebSocketManager.accountSessionExpired = true
                val networkSession: NetworkSession by di.instance()
                networkSession.showMessage(result.error, "Warning", onCancel = {
                    networkSession.clearData("websocketEvent account-session-expired}")
                }, isLastDialog = true)
            }

            errorCallback(result.error)
            removeCallback(result.event)
            return true
        }
        return false
    }

    private fun removeCallback(event: String) {
        successCallbacks[event] = {}
        errorCallbacks[event] = {}
    }

    private fun convertSocketReceivedObject(data: SocketReceivedObject?): SocketReceived? {
        return data?.let { SocketReceived(it.event, it.data?.toString(), it.error, it.status) }
    }

    private fun convertSocketReceivedPrimitive(data: SocketReceivedPrimitive?): SocketReceived? {
        return data?.let { SocketReceived(it.event, it.data?.toString(), it.error, it.status) }
    }

}