package managers

import androidx.compose.runtime.Composable
import kotlinx.browser.window

@Suppress("EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING")
actual class WebBrowserManager {
    actual fun showWebPage(webPage: String) {
        window.open(webPage)
    }

    @Composable
    actual fun ShowWebPage(webPage: String, onBackClick: () -> Unit) {
        window.open(webPage)
    }

}