class AccountWorkConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountWork {
            var item = AccountWork.DO_NOT_SHOW
            enumValues<AccountWork>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}