import fiori.sharedmodule.generated.resources.language_german
import fiori.sharedmodule.generated.resources.language_italian
import fiori.sharedmodule.generated.resources.language_japanese
import fiori.sharedmodule.generated.resources.language_korean
import fiori.sharedmodule.generated.resources.language_portuguese
import fiori.sharedmodule.generated.resources.language_russian
import fiori.sharedmodule.generated.resources.language_spanish
import fiori.sharedmodule.generated.resources.language_swedish
import fiori.sharedmodule.generated.resources.language_ukrainian
