enum class Languages(val value: StringResource, val locale: String) {
    ENGLISH(Res.string.language_english, "en"),
    PORTUGUESE(Res.string.language_portuguese, "pt"),
    RUSSIAN(Res.string.language_russian, "ru"),
    UKRAINIAN(Res.string.language_ukrainian, "uk"),
    SPANISH(Res.string.language_spanish, "es"),
    GERMAN(Res.string.language_german, "de"),
    DUTCH(Res.string.language_danish, "nl"),
    ITALIAN(Res.string.language_italian, "it"),
    SWEDISH(Res.string.language_swedish, "sv"),
    FRENCH(Res.string.language_french, "fr"),
    KOREAN(Res.string.language_korean, "ko"),
    JAPANESE(Res.string.language_japanese, "ja");

    companion object {
        fun getQuestionText(language: String, currentQuestion: CompatibilityQuestion): String? {
            return when (language) {
                RUSSIAN.locale -> currentQuestion.ru ?: currentQuestion.en
                UKRAINIAN.locale -> currentQuestion.uk ?: currentQuestion.en
                PORTUGUESE.locale -> currentQuestion.pt ?: currentQuestion.en
                SPANISH.locale -> currentQuestion.es ?: currentQuestion.en
                GERMAN.locale -> currentQuestion.de ?: currentQuestion.en
                DUTCH.locale -> currentQuestion.nl ?: currentQuestion.en
                ITALIAN.locale -> currentQuestion.it ?: currentQuestion.en
                SWEDISH.locale -> currentQuestion.sv ?: currentQuestion.en
                FRENCH.locale -> currentQuestion.fr ?: currentQuestion.en
                KOREAN.locale -> currentQuestion.ko ?: currentQuestion.en
                JAPANESE.locale -> currentQuestion.ja ?: currentQuestion.en
                else -> currentQuestion.en
            }
        }

        fun getAnswerText(language: String, currentQuestion: CompatibilityQuestionAnswer): String? {
            return when (language) {
                RUSSIAN.locale -> currentQuestion.ru ?: currentQuestion.en
                UKRAINIAN.locale -> currentQuestion.uk ?: currentQuestion.en
                PORTUGUESE.locale -> currentQuestion.pt ?: currentQuestion.en
                SPANISH.locale -> currentQuestion.es ?: currentQuestion.en
                GERMAN.locale -> currentQuestion.de ?: currentQuestion.en
                DUTCH.locale -> currentQuestion.nl ?: currentQuestion.en
                ITALIAN.locale -> currentQuestion.it ?: currentQuestion.en
                SWEDISH.locale -> currentQuestion.sv ?: currentQuestion.en
                FRENCH.locale -> currentQuestion.fr ?: currentQuestion.en
                KOREAN.locale -> currentQuestion.ko ?: currentQuestion.en
                JAPANESE.locale -> currentQuestion.ja ?: currentQuestion.en
                else -> currentQuestion.en
            }
        }
    }
}