 */
@Suppress("EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING", "UNCHECKED_CAST")
actual class MergeObjectsUtils {
    actual companion object {
        actual fun <T> mergeObjects(first: T?, second: T?): T? {
            return if (first is Account? && second is Account?) {
                mergeObjectsWithSerializer(first, second, Account.serializer()) as T?
            } else if (first is AccountFilter? && second is AccountFilter?) {
                mergeObjectsWithSerializer(first, second, AccountFilter.serializer()) as T?
            } else if (first is ChatDialog? && second is ChatDialog?) {
                mergeObjectsWithSerializer(first, second, ChatDialog.serializer()) as T?
            } else if (first is ProfileWow? && second is ProfileWow?) {
                mergeObjectsWithSerializer(first, second, ProfileWow.serializer()) as T?
            } else first
        }

        private fun <T> mergeObjectsWithSerializer(
            new: T?, old: T?, serializer: KSerializer<T>
        ): T? {
            if (new == null || old == null) return new ?: old

            val json = Json {
                isLenient = true; ignoreUnknownKeys = true; explicitNulls = false;
                encodeDefaults = true
            }


            val firstJsonElement = json.encodeToJsonElement(serializer, new) as JsonObject
            val secondJsonElement = json.encodeToJsonElement(serializer, old) as JsonObject
            val mergedMap = secondJsonElement.toMutableMap()

            firstJsonElement.forEach { (key, newValue) ->
                val oldValue = mergedMap[key]

                if (oldValue is JsonObject && newValue is JsonObject) {
                    val mergedNestedJsonObject = mergeJsonObjects(oldValue, newValue)
                    mergedMap[key] = mergedNestedJsonObject
                } else if (newValue is JsonArray && newValue.isEmpty()) {
                    mergedMap[key] = newValue
                } else if (newValue !is JsonNull) {
                    mergedMap[key] = newValue
                }
            }

            val mergedJsonObject = JsonObject(mergedMap)
            return json.decodeFromJsonElement(serializer, mergedJsonObject) as T
        }


        private fun mergeJsonObjects(new: JsonObject, old: JsonObject): JsonObject {
            val mergedMap = old.toMutableMap()

            new.forEach { (key, newValue) ->
                val oldValue = mergedMap[key]

                if (oldValue is JsonObject && newValue is JsonObject) {
                    mergedMap[key] = mergeJsonObjects(new = newValue, old = oldValue)
                } else if (newValue is JsonArray && newValue.isEmpty()) {
                    mergedMap[key] = oldValue ?: JsonNull // Retain firstValue if present, else null
                } else if (newValue !is JsonNull) {
                    mergedMap[key] = newValue
                }
            }
            return JsonObject(mergedMap)
        }
    }

}