package managers

import kotlinx.browser.document
import kotlinx.browser.window
import kotpref.logging.CommonLogger
import kotpref.logging.LogLvl
import org.w3c.dom.HTMLScriptElement
import kotlin.js.Promise.Companion.resolve

@Suppress(names = ["EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING"])
actual class MixPanelManager {

    private var initialized = false
    private var queue = mutableListOf<Pair<AmplitudeEvent, Map<String, Any?>>>()

    private val stub = """
(function(f,b){
    if(!b.__SV){
        var a,e,i,g;
        window.mixpanel = b;
        b._i=[];
        b.init = function(token, config, name){
            function p(obj, methodName){
                var parts = methodName.split(".");
                if (parts.length == 2) {
                    obj = obj[parts[0]];
                    methodName = parts[1];
                }
                obj[methodName] = function(){
                    obj.push([methodName].concat(Array.prototype.slice.call(arguments,0)))
                }
            }
            var target = b;
            if (name !== undefined) {
                target = b[name] = [];
            } else {
                name = "mixpanel";
            }
            target.people = target.people || [];
            target.toString = function(_){
                var str = "mixpanel";
                if (name !== "mixpanel") str += "." + name;
                if (!_ ) str += " (stub)";
                return str;
            };
            target.people.toString = function(){
                return target.toString(1) + ".people (stub)"
            };
            i="disable time_event track track_pageview track_links track_forms register register_once alias unregister identify name_tag set_config reset people.set people.set_once people.unset people.increment people.append people.union people.track_charge people.clear_charges people.delete_user"
                .split(" ");
            for(g=0; g < i.length; g++) p(target, i[g]);
            b._i.push([token, config, name]);
        };
        b.__SV = 1.2;
    }
   })(document, window.mixpanel || []);
    """.trimIndent()

    fun init() {
        if (initialized) {
            resolve(Unit)
            return
        }
        val mixPanelToken = "e6cc1c6f4408541ceb3058d104c3be29"

        // 1) вставляем stub (он создаёт window.mixpanel)
        val stubScript = document.createElement("script") as HTMLScriptElement
        stubScript.type = "text/javascript"
        stubScript.text = stub
        document.head!!.appendChild(stubScript)

        // 2) грузим SDK, который заменит stub на реальную реализацию
        val sdk = document.createElement("script") as HTMLScriptElement
        sdk.async = true
        sdk.src = "https://cdn.mxpnl.com/libs/mixpanel-2-latest.min.js"

        sdk.onload = {
            window.asDynamic().mixpanel.init(mixPanelToken)
            initialized = true
            CommonLogger().log(LogLvl.DEBUG, "MixPanelManager", "initialized onLoad")
            checkQueue()
        }

        document.head?.appendChild(sdk)
    }

    private fun checkQueue() {
        if (queue.isNotEmpty()) {
            val item = queue.first()
            queue.remove(item)
            sending(item.first, item.second)
        }
    }

    private fun sending(event: AmplitudeEvent, params: Map<String, Any?>) {
        if (params.isEmpty()) {
            CommonLogger().log(
                LogLvl.DEBUG,
                "MixPanelManager",
                "sendEvent ${event.name}; with params = $params"
            )
            //val jsonProps = json(*params.toList().toTypedArray())
            //val jsProps = createJsObject(params)
            val jsProps = mapToJs(params)
            window.asDynamic().mixpanel.track(event, jsProps)
        } else {
            window.asDynamic().mixpanel.track(event)
            CommonLogger().log(LogLvl.DEBUG, "MixPanelManager", "sendEvent ${event.name}")
        }
        checkQueue()
    }

    fun mapToJs(props: Map<String, Any?>): dynamic =
        js("JSON.parse")(JSON.stringify(props))

    private fun createJsObject(map: Map<String, Any?>): dynamic {
        val obj = js("{}")
        map.forEach { (k, v) -> obj[k] = v }
        return obj
    }

    private fun Any?.asJsObject(): dynamic {
        return this.unsafeCast<dynamic>()
    }

    actual fun sendIdentify(event: AmplitudeEvent, value: String) {

    }

    actual fun sendIdentify(key: String, value: String) {

    }

    actual fun sendIdentifies(properties: HashMap<String, String>) {
    }

    actual fun sendEvent(event: AmplitudeEvent, params: Map<String, Any?>) {
        if (!initialized) {
            queue.add(event to params)
            return
        }

        if (queue.isNotEmpty()) {
            queue.add(event to params)
            checkQueue()
        } else {
            sending(event, params)
        }
    }
}