@Composable
fun ProfilePhotosSelectScreen(
    fromPage: PhotosFromPage,
    viewModelCallback: (ProfileSelectPhotosEvent) -> Unit,
    viewModel: ProfileSelectPhotosVM = rememberJsViewModel {
        ProfileSelectPhotosVM(fromPage, viewModelCallback)
    }
) {
    PageContainer {
        Column(Modifier.fillMaxSize(), horizontalAlignment = Alignment.CenterHorizontally) {
            Box(modifier = Modifier.fillMaxWidth()) {
                JsCustomTabBar(
                    onBack = { viewModel.backButtonClick() },
                    withBackground = false,
                    isColor = false,
                    tabBarType = TabBars.TabBarWithRightButton(
                        rightButtonTitle = stringResource(resource = Res.string.onboarding_start_btn_text_next),
                        onRightButtonClick = { viewModel.clickedBtn(true) }
                    )
                )
            }

            DragAndDropGridJs(viewModel)
            Box(modifier = Modifier.weight(1f).minHeight(26.dp))
            SplashFiorryButton(
                title = stringResource(resource = Res.string.onboarding_start_btn_text_next)
            ) { viewModel.clickedBtn(false) }
            Box(modifier = Modifier.height(26.dp))
        }

        JsAnimatedVisibility(
            visible = viewModel.showMenuPhotosBottomSheet.value,
            durationMs = 500
        ) {
            Box(
                Modifier.fillMaxSize()
                    .background(color = JsMainTheme.colors.main_color_black_transparent_70)
                    .clickable { viewModel.onMenuCancelClick() }
            ) {
                MenuPhotosBottomSheetJs(
                    modifier = Modifier.align(Alignment.BottomCenter),
                    onMenuCameraClick = {
                        getImageFromGallery {
                            viewModel.pickPhoto = it ?: ""
                            viewModel.showCropPhotoScreen.value = true
                        }
                    },
                    onMenuPhotosClick = {
                        getImageFromGallery {
                            viewModel.pickPhoto = it ?: ""
                            viewModel.showCropPhotoScreen.value = true
                        }
                    },
                )
            }
        }


        JsAnimatedVisibility(
            visible = viewModel.showCropPhotoScreen.value,
            animationDirection = AnimationDirection.RIGHT_TO_LEFT,
            durationMs = 500
        ) {
            ProfilePhotoCropScreenJs(viewModel.pickPhoto, onBack = {
                viewModel.showCropPhotoScreen.value = false
                viewModel.pickPhoto = ""
            }) {

            }
        }
    }
}

@Composable
fun DragAndDropGridJs(viewModel: ProfileSelectPhotosVM) {
    val items = remember { mutableStateListOf(*Array(9) { it }) }
    val photosSize = viewModel.photosListFlow.value.size
    val columns = if (!isMobileDevice) 4 else 3

    CustomVerticalGridLayoutJs(
        columns = columns,
        modifier = Modifier.fillMaxWidth().padding(16.dp),
        horizontalSpacing = 12,
        verticalSpacing = 14,
    ) {
        items.forEach { index ->
            val photo = if (index < photosSize) viewModel.photosListFlow.value[index] else null
            if (index == 0) {
                item(spanX = 2, spanY = 2) {
                    ProfileSelectPhotosItemJs(
                        index = index,
                        photo = null,
                        selectedPhotoIndex = viewModel.selectedPhoto.value,
                        showAddPhoto = photosSize == index,
                        addPhotoClick = { viewModel.addPhotoClick() },
                        longPhotoClick = { viewModel.longPhotoClick(it) },
                        deletePhotoClick = { viewModel.deletePhotoClick(it) },
                        rollBack = { viewModel.rollbackPhoto(it) }
                    )
                }
            } else {
                item {
                    ProfileSelectPhotosItemJs(
                        index = index,
                        photo = null,
                        selectedPhotoIndex = viewModel.selectedPhoto.value,
                        showAddPhoto = photosSize == index,
                        addPhotoClick = { viewModel.addPhotoClick() },
                        longPhotoClick = { viewModel.longPhotoClick(it) },
                        deletePhotoClick = { viewModel.deletePhotoClick(it) },
                        rollBack = { viewModel.rollbackPhoto(it) }
                    )
                }
            }
        }
    }
}

private fun getImageFromGallery(onImageSelected: (String?) -> Unit) {
    val input = document.createElement("input") as HTMLInputElement
    input.type = "file"
    input.accept = "image/*"

    input.onchange = { _ ->
        val file = input.files?.get(0)
        if (file != null) {
            val reader = FileReader()
            reader.onload = { _ ->
                val result = reader.result as? String
                if (result != null) {
                    onImageSelected(result)
                } else {
                    onImageSelected(null)
                }
            }
            reader.readAsDataURL(file)
        }
    }
    input.click()
}