@Composable
fun OnBoardingAgeScreen(
    viewModelCallback: (OnBoardingAgeEvent) -> Unit,
    viewModel: OnBoardingAgeVM = rememberJsViewModel { OnBoardingAgeVM(viewModelCallback) }
) {
    PageContainer {
        Column(
            modifier = Modifier.fillMaxSize(),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            val tabBarType = TabBars.EmptyTabBar/*TabBarWithRightButton(
                onRightButtonClick = { viewModel.clickedBtn(true) },
                rightButtonTitle = stringResource(resource = Res.string.onboarding_start_btn_text_next)
            )*/

            JsCustomTabBar(
                onBack = { viewModel.back() },
                withBackground = false,
                tabBarType = tabBarType
            )

            Box(modifier = Modifier.weight(1f).fillMaxWidth()) {
                if (viewModel.initPage.value) OnBoardingAgeContent(viewModel)
            }

            SplashFiorryButton(
                title = stringResource(resource = Res.string.onboarding_start_btn_text_next)
            ) { viewModel.clickedBtn() }
            Box(modifier = Modifier.height(26.dp))
        }

        if (!viewModel.initPage.value) LoadingState()
        else if (viewModel.showingProgress.value) LoadingBlockState()
    }
}

@Composable
fun OnBoardingAgeContent(viewModel: OnBoardingAgeVM) {
    Column(
        modifier = Modifier.fillMaxSize(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Box(modifier = Modifier.fillMaxHeight(0.08f.toPercent()))

        JsImageView(
            "ic_onboarding_age_web",
            format = "webp",
            modifier = Modifier.fillMaxWidth(40.percent)
        )

        Spacer(modifier = Modifier.height(24.dp))

        JsAutoResizeText(
            text = stringResource(resource = Res.string.onboarding_age_title),
            modifier = Modifier.fillMaxWidth(0.8f.toPercent()),
            color = JsMainTheme.colors.text_color_default,
            fontWeight = FontWeight.Bold,
            maxTextSize = 24,
            minTextSize = 14,
            textAlign = TextAlign.Center,
            maxLines = 2
        )
        Box(
            modifier = Modifier.fillMaxWidth(90.percent).padding(top = 50.dp, bottom = 24.dp),
            contentAlignment = Alignment.Center
        ) {
            SeekBarAgeItem(
                ageText = viewModel.peopleAgeText,
                currentMinValue = viewModel.lastMinAge.value,
                currentMaxValue = viewModel.lastMaxAge.value,
                onProgressChange = { min, max ->
                    viewModel.onProgressChange(currentMin = min, currentMax = max)
                }
            )
        }
    }
}

@Composable
fun SeekBarAgeItem(
    ageText: MutableState<String>,
    currentMinValue: Int,
    currentMaxValue: Int,
    trackColor: Color = JsMainTheme.colors.app_main_color,
    onProgressChange: (Int, Int) -> Unit
) {
    Column(
        Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        JsTextView(
            text = ageText.value,
            modifier = Modifier.padding(bottom = 24.dp),
            textColor = JsMainTheme.colors.text_color_default,
            textSize = 22,
            fontWeight = FontWeight.Medium
        )

        web.views.DefaultRangeSlider(
            Modifier.fillMaxWidth(85.percent).height(30.dp),
            currentMinValue = currentMinValue,
            currentMaxValue = currentMaxValue,
            activeTrackColor = trackColor,
            onProgressChange = { currentMin, currentMax ->
                onProgressChange.invoke(currentMin, currentMax)
            }
        )
    }
}