package fiori.transgender.ui.kotpref.models.chat

import kotlinx.serialization.SerialName
import kotlinx.serialization.Transient
import kotpref.models.chat.ChatImage
import kotpref.models.chat.ChatMessageStatus
import kotpref.models.chat.ChatUser
import kotpref.models.chat.LastMessageItem
import kotpref.models.chat.MessageContentType

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-07-05.
 */

//@Entity
@kotlinx.serialization.Serializable
class ChatMessageItem constructor(

    //@ColumnInfo(name = "chat_message_item_id")
    @SerialName("id") private val id: String,

    //@Embedded
    //@ColumnInfo(name = "chat_message_item_user")
    @SerialName("user") private val user: ChatUser,

    //@ColumnInfo(name = "chat_message_item_text")
    @SerialName("text") private var text: String?,

    //@ColumnInfo(name = "chat_message_item_type")
    @SerialName("type") var type: Int,

    //@ColumnInfo(name = "chat_message_item_create_at")
    @SerialName("createdAt") private var createdAt: String? = null,

    //@ColumnInfo(name = "chat_status")
    @Transient
    var status: ChatMessageStatus = ChatMessageStatus.SENDING,

//    @Ignore
    @SerialName("status") var statusString: String = ChatMessageStatus.SENDING.resId(),

//    @Ignore
    @SerialName("unblured") var unblured: Boolean = false,

    //@Embedded
    //@ColumnInfo(name = "chat_message_item_image")
    @SerialName("image") var image: ChatImage? = null,

//    @Ignore
    @SerialName("isUpdate") var isUpdate: Boolean = false,

//    @Ignore
    @SerialName("firstLoad") var firstLoad: Boolean = true

) : MessageContentType.Image, MessageContentType.Gift, MessageContentType {

    var voice: Voice? = null

    fun getId(): String = id
    fun getText(): String? = text
    fun getCreatedAt(): String? = createdAt
    fun getUser(): ChatUser = this.user

    override val imageUrl: String?
        get() = if (image == null) null else image?.url

    override val messageType: Int = type

    fun setText(text: String) {
        this.text = text
    }

    fun setStatusValue(status: ChatMessageStatus) {
        this.status = status
        statusString = status.resId()
    }

    fun setCreatedAt(createdAt: String?) {
        this.createdAt = createdAt
    }

    @kotlinx.serialization.Serializable
    class Voice(val url: String, val duration: Int)

    fun toLast(): LastMessageItem = LastMessageItem(id, user.toLast(), text, type, createdAt)
}
