package dependencies

import kotlinx.browser.window
import kotpref.models.AppVariant
import kotpref.models.UserAgent
import kotpref.stores.IAppKeysStorage
import kotpref.utils.IAppKeysSecureDefault
import kotpref.utils.IDialogManager
import kotpref.utils.IImageUtils
import kotpref.utils.ILocationUtils
import kotpref.utils.INotificationManager
import kotpref.utils.IPickPhotoManager
import kotpref.utils.IPlatformInfoManager
import kotpref.utils.PlatformType
import managers.AdaptyManager
import managers.AmplitudeManager
import managers.BillingManager
import managers.IBillingManager
import managers.IFirebaseManager
import managers.ImageUtils
import managers.LocationUtils
import managers.MixPanelManager
import managers.NotificationsUtils
import managers.PickPhotoManager
import managers.PlatformInfoManager
import managers.WebBrowserManager
import managers.WebDialogManager
import network.RetrofitSession
import network.restApi.NetworkSession
import org.kodein.di.DI
import org.kodein.di.bind
import org.kodein.di.instance
import org.kodein.di.singleton
import storage.AppKeysSecureDefault
import storage.AppKeysStorage
import storage.Database
import storage.IDatabase
import ui.managers.NicknameChangeManager


class WebDependencies {

    init {
        val userAgent = hashMapOf<String, String>()
        DependenciesContainer(
            listOf(managersDependencies()),
            { userAgent },
            listOf(webDependencies())
        )
    }

    private fun managersDependencies() = DI.Module("Managers module", true) {
        bind<WebBrowserManager>() with singleton { WebBrowserManager() }
        bind<NicknameChangeManager>() with singleton { NicknameChangeManager() }
        bind<IPickPhotoManager>() with singleton { PickPhotoManager() }
        bind<IDatabase>() with singleton { Database() }
        bind<IDialogManager>() with singleton { WebDialogManager() }
        bind<IAppKeysStorage>() with singleton { AppKeysStorage() }
        bind<IAppKeysSecureDefault>() with singleton { AppKeysSecureDefault() }
        bind<IPlatformInfoManager>() with singleton { PlatformInfoManager() }
        bind<INotificationManager>() with singleton { NotificationsUtils() }
        bind<IImageUtils>() with singleton { ImageUtils() }
        bind<ILocationUtils>() with singleton { LocationUtils() }
        bind<AmplitudeManager>() with singleton { AmplitudeManager() }
        bind<MixPanelManager>() with singleton { MixPanelManager() }
        bind<IFirebaseManager>() with singleton { FirebaseManager() }
    }

    private fun webDependencies() = DI.Module("Web module", true) {
        bind<AdaptyManager>() with singleton { AdaptyManager() }
        bind<IBillingManager>() with singleton { BillingManager(instance()) }

        bind<NetworkSession>() with singleton {

            var appVersion =
                if (AppVariant.isElizium()) "2.8.0"
                else if (AppVariant.isHeaven()) "1.4.0"
                else if (AppVariant.isParadiz()) "1.4.0"
                else "4.6.0"

            var appId =
                if (AppVariant.isElizium()) "local.date"
                else if (AppVariant.isHeaven()) "heaven.date"
                else if (AppVariant.isParadiz()) "paradiz.date"
                else "fiori.transgender"
            if (AppVariant.isDev()) appId += ".stage"

            val platform = when (PlatformInfoManager().getPlatformType()) {
                PlatformType.iOS -> "iOS"
                PlatformType.Android -> "Android"
                PlatformType.WebIOS -> "Web iOS"
                PlatformType.WebAndroid -> "Web Android"
                PlatformType.WebMacBook -> "Web MacBook"
                PlatformType.Web -> "Web"
            }

            val userAgent = UserAgent(
                appId,
                "1",
                androidVersion = window.navigator.appVersion,
                deviceName = window.navigator.userAgent,
                platform = platform,
                appVersion = appVersion
            )

            val session = RetrofitSession(
                dialogManager = instance(),
                sessionEndpoint = instance(),
                sessionAppKeys = instance(),
                platformInfoManager = instance(),
                sessionLogger = instance(),
                sessionUserAgent = userAgent,
                notificationsUtils = instance()
            )
            session
        }
    }

}
