        )*/
    }

    private fun moderatePhoto(
        filePath: String,
        moderateApiUser: String,
        moderateApiSecret: String,
        onSuccess: (ModeratePhoto?) -> Unit = {},
        onError: (String?) -> Unit = {}
    ) {
        val imageFile = imageUtils.compressBitmapToFileKMM(
            filePath.replace("file://", ""), "moderatePhoto", 50
        )
        val body = formData {
            append("media", imageFile.bytes, Headers.build {
                append(HttpHeaders.ContentType, "multipart/form-data")
                append(HttpHeaders.ContentDisposition, "filename=${imageFile.name}")
            })
            append("api_user", moderateApiUser)
            append("api_secret", moderateApiSecret)
            append("models", "nudity,wad,offensive")
        }

        val job = CoroutineScope(Dispatchers.Default).launch {
            try {
                val url = "$moderationUrl/check.json"
                val data: ModeratePhoto? = ktorClient.multipartWithResult(url, body)
                CommonLogger().log(LogLvl.DEBUG, "moderatePhotoResult", data.toString())
                //val data = moderationApi.moderatePhoto(body)
                onSuccess(data)

                moderatePhotoCalls.removeFirstOrNull()
            } catch (e: Exception) {
                onError(e.message)
                moderatePhotoCalls.removeFirstOrNull()
            }
        }
        moderatePhotoCalls.add(job)
//        job.start()
    }

    private fun correctPhoto(moderateResult: ModeratePhoto): Boolean = when {
        (moderateResult.nudity.raw ?: 0.0) > 0.7 -> false
        (moderateResult.weapon ?: 0.0) > 0.7 -> false
        (moderateResult.alcohol ?: 0.0) > 0.7 -> false
        (moderateResult.drugs ?: 0.0) > 0.7 -> false
        (moderateResult.offensive.prob ?: 0.0) > 0.7 -> false
        else -> true
    }

    private fun getToken(): String {
        return "Bearer ${appKeys.userToken}"
    }
}